window.SOCIAL_DATA=window.SOCIAL_DATA||[];window.SOCIAL_DATA.push({"id": "hist-4", "subject": "歷史", "chapter": "第四章", "title": "明清時期東亞世界的變動", "total": 171, "levels": {"必考": 12, "常考": 6}, "mapname": {"h4-ming": "明代後期周邊民族與倭寇、流寇示意圖", "h4-qing": "清代盛世疆域圖", "h4-zhenghe": "鄭和下西洋路線圖", "h4-global": "葡萄牙、西班牙人新航路與全球經濟網絡圖"}, "concepts": [{"id": "d11", "name": "西學東漸與利瑪竇等耶穌會傳教士", "n": 23, "level": "必考", "card": {"說明": "明朝末年，天主教耶穌會傳教士伴隨新航路來到東方傳教。為消除中國士大夫的戒心與排外情緒，傳教士利瑪竇採取「適應儒家習俗」的策略，穿儒服、習漢語，並破例允許中國教徒維持祭祖、祭孔的儒家傳統儀節。利瑪竇與明朝內閣官員徐光啟合譯歐幾里得《幾何原本》，將西方火砲、數學、地理學（如《坤輿萬國全圖》）、天文曆法引進中國，開啟「西學東漸」序幕。", "關鍵名詞": "• <b>耶穌會</b>：大航海時代天主教為抗衡宗教改革而在海外積極傳教的修會，以利瑪竇、湯若望為代表。<br>• <b>幾何原本</b>：明末利瑪竇與徐光啟合譯的西方古典數學名著，確立「點、線、面、三角形」等漢語幾何學術名詞。", "因果／影響": "引進西方實用科學與地理新視野，同時傳教士亦將中國儒家經典、瓷器工藝與園林建築介紹回西方，在 18 世紀歐洲掀起一股崇尚東方的「中國熱」。", "出處": "自修第30頁／講義第48頁、速讀秘笈第4章。", "標示": "講義「會考精熟題」、自修「重點精華」。"}, "imgs": [], "clusters": [{"t": "利瑪竇與《幾何原本》", "n": 4, "ids": ["h4-3", "h4-54", "h4-113", "h4-162"]}, {"t": "天主教耶穌會、容許祭祖祭孔", "n": 6, "ids": ["h4-20", "h4-32", "h4-42", "h4-135", "h4-140", "h4-109"]}, {"t": "傳入的西學（不含中國發明）", "n": 4, "ids": ["h4-25", "h4-61", "h4-153", "h4-85"]}, {"t": "中國文化西傳：儒家、瓷器、園林", "n": 5, "ids": ["h4-4", "h4-53", "h4-97", "h4-133", "h4-154"]}, {"t": "東西文化交流", "n": 4, "ids": ["h4-31", "h4-90", "h4-117", "h4-148"]}]}, {"id": "d3", "name": "滿清入關與高壓懷柔並行的統治策略", "n": 23, "level": "必考", "card": {"說明": "女真族（後改族名為滿洲）再度崛起於東北並建立大清帝國。明亡後，清軍在降將吳三桂協助下引兵入山海關，擊潰李自成進占北京。清廷以少數民族入主中原，為鞏固政權採取「高壓與懷柔並行」的統治方針：高壓方面強迫漢人「剃髮留辮」以示臣服，並屢興「文字獄」鎮壓反抗思想；懷柔方面則禮遇明朝遺臣降將、延續科舉取士以籠絡廣大漢人讀書階層。", "關鍵名詞": "• <b>剃髮留辮</b>：清廷強制漢人剃除頭部四周頭髮、編留辮子的民族同化與臣服象徵政策，違反者處以死刑。<br>• <b>文字獄</b>：清朝統治者自文人詩文中摘取字句羅織罪名、興起冤獄以箝制反清思想的高壓手段。", "因果／影響": "有效鞏固了滿清對漢族社會的少數統治，維持政權穩定長達兩百餘年，但深刻打擊了知識分子的學術與思想自由。", "出處": "自修第29頁／講義第45頁、評量單第7回第1頁。", "標示": "自修「重點精華」、講義「重點分析」、段考極高頻考點。"}, "imgs": ["h4-qing"], "clusters": [{"t": "高壓：薙髮留辮、文字獄", "n": 8, "ids": ["h4-7", "h4-10", "h4-14", "h4-44", "h4-50", "h4-55", "h4-72", "h4-100"]}, {"t": "懷柔：照常舉行科舉", "n": 6, "ids": ["h4-57", "h4-136", "h4-152", "h4-78", "h4-107", "h4-65"]}, {"t": "吳三桂引清兵入關", "n": 4, "ids": ["h4-49", "h4-105", "h4-128", "h4-131"]}, {"t": "清朝由女真（滿洲）建立", "n": 3, "ids": ["h4-17", "h4-19", "h4-70"]}, {"t": "外族政權比較、朝代排序", "n": 2, "ids": ["h4-26", "h4-115"]}]}, {"id": "d6", "name": "鄭和下西洋與南洋華人移民", "n": 17, "level": "必考", "card": {"說明": "15 世紀初期，明成祖為宣揚國威、拓展朝貢體系，派三寶太監鄭和率領龐大船隊連續七次出使「西洋」（指今東南亞與印度洋一帶）。船隊最遠航行抵達非洲東岸與紅海口，沿途各國深受吸引與震撼，紛紛派遣使節攜珍奇貢品（如長頸鹿／麒麟）來華朝貢。", "關鍵名詞": "<b>鄭和下西洋</b>——明成祖時期由鄭和率領大規模艦隊七次遠航東南亞、印度洋至非洲東岸的外交遠征航海行動。", "因果／影響": "將明代朝貢體制擴展至印度洋海域，同時促進中國東南沿海居民大批向東南亞（南洋）遷徙經商，奠定南洋華人社會的基礎。", "出處": "自修第30頁／講義第46頁、速讀秘笈第4章。", "標示": "講義「重點分析」、會考歷屆考題。"}, "imgs": ["h4-zhenghe"], "clusters": [{"t": "西洋＝東南亞、印度洋", "n": 5, "ids": ["h4-23", "h4-33", "h4-74", "h4-114", "h4-166"]}, {"t": "明成祖派遣、最遠到非洲東岸", "n": 4, "ids": ["h4-73", "h4-75", "h4-77", "h4-144"]}, {"t": "影響：朝貢擴大、華人移居南洋", "n": 6, "ids": ["h4-15", "h4-24", "h4-76", "h4-106", "h4-142", "h4-167"]}, {"t": "早於新航路，不是新航路的影響", "n": 1, "ids": ["h4-68"]}, {"t": "鄭和的貢獻", "n": 1, "ids": ["h4-41"]}]}, {"id": "d2", "name": "明末流寇之禍與李自成攻陷北京", "n": 14, "level": "必考", "card": {"說明": "明朝中葉後內政腐敗，邊患頻仍；至明末面臨小冰期氣候變遷，天災連年導致大規模乾旱大饑荒，加上人口激增、糧食不足與重稅逼迫，陝西等地的災民與飢餓官兵相結合，爆發席捲各地的民變（流寇）。其中李自成勢力最強，建立大順政權，於西元 1644 年攻陷北京，明思宗（崇禎帝）在煤山自縊，明朝滅亡。", "關鍵名詞": "<b>流寇</b>——明代末年因饑荒天災與重稅而起義的武裝災民與叛兵群體，四處劫掠流動，以李自成為最大領袖。", "因果／影響": "直接終結了統治近三百年的明朝政權，並使山海關總兵吳三桂為報家仇引入清兵入關，造成中原政權易手。", "出處": "自修第29頁／講義第44頁。", "標示": "自修「必考概念」、會考學力診斷重點題。"}, "imgs": ["h4-ming"], "clusters": [{"t": "李自成攻陷北京、明亡", "n": 7, "ids": ["h4-8", "h4-39", "h4-69", "h4-108", "h4-124", "h4-161", "h4-163"]}, {"t": "明末內憂外患辨識", "n": 5, "ids": ["h4-16", "h4-95", "h4-122", "h4-139", "h4-168"]}, {"t": "流寇是官逼民反", "n": 1, "ids": ["h4-83"]}, {"t": "吳三桂引清兵入關", "n": 1, "ids": ["h4-37"]}]}, {"id": "d1", "name": "明帝國的建立與邊防（遷都北京與長城重修）", "n": 13, "level": "必考", "card": {"說明": "元朝末年群雄並起，朱元璋擊敗群雄建立明朝（明太祖），定都應天（今南京），將蒙古勢力逐退至長城以北。退居漠北的蒙古人仍是明朝邊防最主要的威脅；至明成祖時，為加強北方邊防抵禦蒙古進犯，將首都遷至靠近邊境重鎮的北京，形成「天子守國門」的格局，並大舉修築長城以強化北方防禦體系。", "關鍵名詞": "<b>天子守國門</b>——明成祖將首都由南京遷往鄰近北方邊塞的北京，親自防禦蒙古勢力進犯的戰略布局。", "因果／影響": "鞏固了北方防線與國勢鼎盛，但也加重了國家軍費開支負擔，並奠定往後北京作為全國政治中心的歷史地位。", "出處": "自修第29頁／講義第44頁、速讀秘笈第4章。", "標示": "講義「重點分析」、自修「重點精華」。"}, "imgs": ["h4-ming"], "clusters": [{"t": "朱元璋建明、驅逐蒙古", "n": 3, "ids": ["h4-18", "h4-51", "h4-92"]}, {"t": "明成祖：遷都北京、修長城、派鄭和", "n": 3, "ids": ["h4-2", "h4-91", "h4-137"]}, {"t": "北方蒙古、東南倭寇", "n": 3, "ids": ["h4-52", "h4-88", "h4-132"]}, {"t": "明代外患與軍費", "n": 3, "ids": ["h4-48", "h4-111", "h4-127"]}, {"t": "首都北京的位置", "n": 1, "ids": ["h4-22"]}]}, {"id": "d7", "name": "海禁政策與走私武裝海商（倭寇）", "n": 13, "level": "必考", "card": {"說明": "明太祖初年為防備日本流浪武士、商人與海盜組成的「倭寇」侵擾沿海，頒布嚴格的「海禁政策」，嚴格禁止民間私人船隻擅自出海貿易，僅保留官方主導的朝貢互市。然而東南沿海山多田少，人民生計高度依賴海上貿易，禁令反而迫使沿海居民轉入地下從事非法走私，甚至形成兼具武裝力量的海商與海盜集團，加劇了東南沿海的「倭患」動盪。", "關鍵名詞": "• <b>海禁政策</b>：明清時期限制或禁止民間私人造船出海進行海外貿易的嚴格禁令。<br>• <b>倭寇</b>：14至16世紀在中國東南沿海侵擾掠奪的日本海盜，以及與之勾結的中國武裝走私海商集團。", "因果／影響": "至明代中後期朝廷被迫逐步放寬海禁，民間海商勢力在東南沿海、臺灣、日本與東南亞海域活躍經營，帶動區域走私繁榮。", "出處": "自修第30頁／講義第46頁。", "標示": "自修「精熟思考題」、評量單必考題。"}, "imgs": ["h4-ming"], "clusters": [{"t": "明防倭寇、清初打擊鄭氏", "n": 6, "ids": ["h4-12", "h4-59", "h4-119", "h4-158", "h4-159", "h4-169"]}, {"t": "倭寇與走私海商", "n": 4, "ids": ["h4-36", "h4-63", "h4-104", "h4-87"]}, {"t": "海禁的影響", "n": 3, "ids": ["h4-30", "h4-89", "h4-160"]}]}, {"id": "d12", "name": "禮儀之爭與清廷禁教", "n": 12, "level": "必考", "card": {"說明": "清朝初期，羅馬教廷其他修會對耶穌會寬容教徒祭祖祭孔的作法提出質疑，教宗下令嚴格禁止中國天主教徒遵行祭祖、祭孔禮俗，清聖祖康熙帝對此干涉中國傳統文化之舉極度不滿，爆發「禮儀之爭」。至清世宗雍正帝即位後，因部分傳教士牽涉宮廷皇位爭奪政爭，加上擔心西方勢力滲透，雍正帝正式下令「全面禁教」，將外國傳教士驅逐出境（除少數留京任職科技官員除外）。", "關鍵名詞": "<b>禮儀之爭</b>——17至18世紀天主教羅馬教廷與清朝朝廷之間，針對中國天主教徒是否能維持「祭祖、祭孔」傳統禮俗所引發的嚴重宗教外交爭端。", "因果／影響": "自明末以來蓬勃發展的百餘年中西科技與思想文化交流自此中斷，加深了清朝閉關排外的傾向。", "出處": "自修第30頁／講義第48頁、評量單第8回第1頁。", "標示": "講義「重點分析」、自修「必考概念」。"}, "imgs": [], "clusters": [{"t": "雍正禁教，中西交流中斷", "n": 7, "ids": ["h4-9", "h4-67", "h4-102", "h4-141", "h4-143", "h4-86", "h4-126"]}, {"t": "禁教原因：傳教士涉入宮廷政爭", "n": 4, "ids": ["h4-71", "h4-79", "h4-145", "h4-165"]}, {"t": "雍正的父親是康熙", "n": 1, "ids": ["h4-146"]}]}, {"id": "d10", "name": "全球貿易網絡與美洲白銀流入（銀錢並用制）", "n": 12, "level": "必考", "card": {"說明": "歐洲人開闢新航路後，西班牙、葡萄牙等國商人在全球建立跨洋商業航線。歐洲商人開採美洲盛產的白銀（以及日本白銀），運至亞洲大量收購中國優質的絲綢、瓷器與茶葉等商品再轉售至歐美各地，促成大量美洲白銀流入中國。", "關鍵名詞": "<b>銀錢並用</b>——明代後期因外洋白銀巨額流入，淘汰了過往容易貶值的紙幣，確立以白銀為大額交易主幣、銅錢為小額流通幣的貨幣體制。", "因果／影響": "加速了中國捲入早期全球化經濟體系中，並促使政府改革稅制（如推行將田賦與勞役合併折銀徵收的制度），白銀成為社會最核心的金融流通資產。", "出處": "自修第30頁／講義第47頁、會考補考精選題。", "標示": "講義「重點分析」、會考經典題。"}, "imgs": ["h4-global"], "clusters": [{"t": "白銀流入、銀錢並用", "n": 6, "ids": ["h4-56", "h4-82", "h4-99", "h4-103", "h4-151", "h4-156"]}, {"t": "白銀來自美洲、經菲律賓轉運", "n": 2, "ids": ["h4-130", "h4-155"]}, {"t": "西葡商人收購絲綢瓷器", "n": 3, "ids": ["h4-34", "h4-93", "h4-157"]}, {"t": "明中葉到清初的對外交流", "n": 1, "ids": ["h4-60"]}]}, {"id": "d13", "name": "江戶幕府鎖國政策與蘭學", "n": 11, "level": "常考", "card": {"說明": "16 世紀天主教傳入日本後迅速蔓延，引發統治階層憂心外國勢力動搖統治與社會安寧。17 世紀德川幕府為防範天主教滲透及控制海外通商利潤，斷然實施「鎖國政策」，嚴厲驅逐西方傳教士與西班牙、葡萄牙商人，僅保留「長崎」一處港口，有限度允許「中國」商船與未傳教的「荷蘭」商船進港貿易。", "關鍵名詞": "<b>蘭學</b>——日本鎖國期間，透過長崎唯一合法通商的荷蘭商人所傳入的西方天文、醫學、槍砲等近代科學技術之學術統稱。", "因果／影響": "日本維持了兩百多年的國內封閉穩定，長崎出島的荷蘭貿易窗口亦為日本保留了接觸西方近代科學的管道，為日後近代化奠定基礎。", "出處": "自修第30頁／講義第49頁。", "標示": "講義「重點整理」、會考歷屆考題。"}, "imgs": [], "clusters": [{"t": "只開放長崎給中國、荷蘭", "n": 5, "ids": ["h4-40", "h4-62", "h4-81", "h4-101", "h4-170"]}, {"t": "荷蘭帶入蘭學", "n": 3, "ids": ["h4-6", "h4-121", "h4-171"]}, {"t": "鎖國、禁止天主教", "n": 3, "ids": ["h4-1", "h4-58", "h4-120"]}]}, {"id": "d5", "name": "天朝體制與朝貢貿易制度", "n": 9, "level": "常考", "card": {"說明": "明清兩朝在對外關係上皆以「天朝」自居，建構以中國為宗主核心的「天朝體制」與國際交往觀念。外國必須接受中國皇帝的「冊封」、向天朝進貢，建立名義上的君臣宗藩關係，才能獲得許可藉「進貢」之名義隨行開展通商貿易，稱為「朝貢貿易」（如琉球、朝鮮、越南等國）。", "關鍵名詞": "<b>天朝體制</b>——中國歷代王朝以天朝自居，透過封冊、進貢等禮制維繫以中國為核心之宗主與藩屬國際外交秩序。", "因果／影響": "鞏固了東亞以中國為尊的朝貢秩序與政治威信，成為明清時期東亞官方合法經貿交往的唯一正式管道。", "出處": "自修第30頁／講義第46頁。", "標示": "講義「會考精熟題」、自修「必考重點」。"}, "imgs": [], "clusters": [{"t": "接受冊封才能進貢貿易", "n": 4, "ids": ["h4-13", "h4-46", "h4-84", "h4-96"]}, {"t": "海禁下只剩朝貢貿易", "n": 4, "ids": ["h4-66", "h4-116", "h4-118", "h4-149"]}, {"t": "清初對外貿易", "n": 1, "ids": ["h4-29"]}]}, {"id": "d9", "name": "美洲作物引進（番薯、玉米、馬鈴薯）", "n": 8, "level": "常考", "card": {"說明": "15 世紀末大航海時代（新航路開闢）之後，原產於美洲的高產耐旱作物如玉米、番薯（地瓜）、馬鈴薯（洋芋）等，由西方探險家與貿易商人陸續引進中國與東亞種植。這些新作物耐旱耐瘠、不與傳統水稻爭奪良田，極適合在丘陵、高地與邊陲山區廣泛栽種。", "關鍵名詞": "<b>美洲作物</b>——大航海時代後由美洲經歐洲與海商引進的非傳統糧食作物，以玉米、番薯、馬鈴薯為代表。", "因果／影響": "大幅擴充了糧食供應與熱量來源，緩和了明清時期因人口暴增所帶來的嚴重糧食短缺危機，促使人口突破數億大關。", "出處": "自修第30頁／講義第47頁、評量單第8回第2頁。", "標示": "講義「會考重點」、自修「極高頻考點」。"}, "imgs": ["h4-global"], "clusters": [{"t": "明代由歐洲人從美洲傳入", "n": 5, "ids": ["h4-28", "h4-64", "h4-98", "h4-112", "h4-134"]}, {"t": "解決人口增加的糧食問題", "n": 3, "ids": ["h4-123", "h4-138", "h4-150"]}]}, {"id": "d4", "name": "康雍乾盛世與近代中國版圖奠定", "n": 7, "level": "常考", "card": {"說明": "清朝在康熙、雍正、乾隆三代連續百餘年間，國家政局穩定、國力達到極盛，史稱「康雍乾盛世」。在此期間，清廷陸續向外開疆拓土，先後將蒙古、臺灣（康熙時派施琅攻滅鄭氏政權）、西藏、新疆（乾隆平定準噶爾部）等地納入直轄或管轄版圖。", "關鍵名詞": "<b>康雍乾盛世</b>——指清初康熙、雍正、乾隆三朝延續百餘年文治武功鼎盛、國力強大與疆域擴張的盛世時期。", "因果／影響": "將多元民族融為一體，使帝國版圖遠超明代傳統漢地疆界，奠定了今日近代中國疆域的基礎輪廓。", "出處": "自修第29頁／講義第45頁。", "標示": "講義「重點分析」、自修基礎實力題。"}, "imgs": ["h4-qing"], "clusters": [{"t": "新疆、西藏在清代納入版圖", "n": 3, "ids": ["h4-5", "h4-35", "h4-47"]}, {"t": "康雍乾的文治武功", "n": 3, "ids": ["h4-110", "h4-164", "h4-21"]}, {"t": "草原與農業民族對峙結束", "n": 1, "ids": ["h4-147"]}]}, {"id": "d8", "name": "國內手工業與專業市鎮興起（如景德鎮）", "n": 5, "level": "一般", "card": {"說明": "明清時期國內商品經濟高度活躍，手工業生產分工日趨細密繁複，農村與交通要道周邊紛紛湧現許多具有特定專業產業特色的小城鎮，稱為「專業市鎮」。例如江西景德鎮以生產精美瓷器名揚天下，被譽為瓷都；其他江南市鎮亦分別專精於絲織、棉紡織等產業。", "關鍵名詞": "<b>專業市鎮</b>——明清時期因特定手工業商品（如製瓷、絲織、棉紡）高度分工與商業貿易聚集而蓬勃興起的新興城鎮。", "因果／影響": "市鎮間生產的專業商品頻繁長途交流互通，不僅帶動國內統一市場的繁榮，更充實了大量供應海外出口的高價值商品來源。", "出處": "自修第29頁／講義第46頁。", "標示": "自修「重點精華」、講義「重點分析」。"}, "imgs": [], "clusters": [{"t": "景德鎮與專業市鎮", "n": 5, "ids": ["h4-11", "h4-43", "h4-94", "h4-125", "h4-129"]}]}, {"id": "d14", "name": "跨章綜合辨識", "n": 4, "level": "一般", "card": {}, "imgs": [], "clusters": [{"t": "跨章比較", "n": 3, "ids": ["h4-27", "h4-38", "h4-45"]}]}], "questions": [{"id": "h4-1", "no": 1, "c": "d13", "src": "考卷 114上翰林社會2上A卷 卷5 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "聯合國教科文組織正式將「長崎與天草地區隱藏基督徒相關遺產」登記為世界文化遺產，該遺產分布在日本長崎附近，隨著這些「隱藏教會」被公諸於世，更確立了 17 世紀基督教在日本受迫害的足跡。上述基督教在發展受阻與下列何者有關？", "o": ["大化革新", "鎖國政策", "朝貢貿易", "清廷禁教"], "a": 1, "e": "17 世紀德川幕府實施鎖國、禁止天主教，基督徒只好隱藏信仰，所以和鎖國政策有關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-2", "no": 2, "c": "d1", "src": "考卷 114上翰林社會2上A卷 卷5 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "電視劇《大明風華》描述建文4年，朱棣攻下帝都應天，自立為帝，他將首都遷到北京、修築長城，並經營南洋、揚威海外。該劇中「朱棣」最可能是下列何人？", "o": ["明太祖", "明成祖", "康熙皇帝", "雍正皇帝"], "a": 1, "e": "朱棣就是明成祖，他遷都北京、修築長城，並派鄭和下西洋經營南洋。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-3", "no": 3, "c": "d11", "src": "考卷 114上翰林社會2上A卷 卷5 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "前副總統陳建仁盛讚利瑪竇是東西文化交流的先驅，引進了西方的科學知識，包括點線面等用語都是其所創造，並沿用至今。上文中的利瑪竇與明朝大臣徐光啟合譯下列哪本書籍？", "o": ["《職貢圖》", "《四書集注》", "《幾何原本》", "《坤輿萬國全圖》"], "a": 2, "e": "利瑪竇與徐光啟合譯《幾何原本》，點、線、面等數學名詞就是從這本書來的。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-4", "no": 4, "c": "d11", "src": "考卷 114上翰林社會2上A卷 卷5 第 4 題", "st": "考卷", "ctx": "", "fig": "圖(一)為 17 世紀歐洲出版書籍中身穿儒服的孔子像", "q": "西方傳教士在明清時期，將中國經典和哲學思想西傳歐洲，一度形成歐洲的「中國熱」。圖(一)是 17 世紀西方書籍中的孔子像，這說明下列哪一學說的經典西傳？", "o": ["儒家", "道家", "墨家", "法家"], "a": 0, "e": "孔子是儒家的代表。傳教士把儒家經典介紹到歐洲，掀起「中國熱」。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-5", "no": 5, "c": "d4", "src": "考卷 114上翰林社會2上A卷 卷5 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "西藏與新疆又稱為「圖博」與「東突厥斯坦」，在歷史上都是首度被納入中國版圖，西藏是「西方的藏土」之意，而新疆則是「新闢的疆土」。上述地區在下列何時始納入中國版圖？", "o": ["唐代", "宋代", "明代", "清代"], "a": 3, "e": "西藏、新疆是在清代（康雍乾時期）才納入中國版圖的。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-qing"], "chk": ""}, {"id": "h4-6", "no": 6, "c": "d13", "src": "考卷 114上翰林社會2上A卷 卷5 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "下表是大航海時代，某國家的海外拓展活動，由內容判斷這個國家應是下列何國？\n成立於 17 世紀初\n設立亞洲總部位於巴達維亞，統籌經營\n在臺灣、南非好望角等地建立殖民地\n在日本鎖國時期，獲准與日本貿易", "o": ["葡萄牙", "西班牙", "英國", "荷蘭"], "a": 3, "e": "17 世紀初成立東印度公司、總部在巴達維亞、占領過臺灣、日本鎖國時仍能貿易的國家是荷蘭。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-7", "no": 7, "c": "d3", "src": "考卷 114上翰林社會2上A卷 卷5 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "長期關注言論自由的美國筆會發表全球寫作自由指數，揭露全球至少 339 名作家或知識分子遭囚禁，其中中國達 107 人，許多被囚者只因評論官方政策或政經情勢就被捕。上述這種從文人文著中摘取字句，羅織罪名的政策，在下列哪一朝代最盛行？", "o": ["北宋", "南宋", "元代", "清代"], "a": 3, "e": "從文人作品中摘取字句、羅織罪名，就是「文字獄」，清代最盛行。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-8", "no": 8, "c": "d2", "src": "考卷 114上翰林社會2上A卷 卷5 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "北京市李自成雕像日前被遷移至其陝西老家「闖王寨」風景區。該人物加入反政府的軍隊，後成為當時民變領袖之一，於 1644 年在西安稱帝，之後更攻入北京，促使皇帝自縊殉國。上述人物的作為導致下列哪個朝代的滅亡？", "o": ["宋", "元", "明", "清"], "a": 2, "e": "李自成在 1644 年攻陷北京，崇禎帝自縊，明朝滅亡。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-9", "no": 9, "c": "d12", "src": "考卷 114上翰林社會2上A卷 卷5 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "明清之際，中西文化交流頻繁，但這樣的景象，卻因清代發生何事而宣告中斷？", "o": ["康熙大興文字獄，排斥西學、洋教", "乾隆積極經營西域，防止歐人東來", "雍正厲行海禁政策，阻止外人入境", "雍正實施禁教，將傳教士逐出中國"], "a": 3, "e": "雍正下令禁教、驅逐傳教士，明清之際的中西文化交流因此中斷。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-10", "no": 10, "c": "d3", "src": "考卷 114上翰林社會2上A卷 卷5 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "滿清入主中國後，曾用多種方式來統治漢人，下列哪一措施屬於清帝國採用的高壓統治方式？", "o": ["推崇儒學", "朝貢貿易", "剃髮留辮", "厚待科舉"], "a": 2, "e": "剃髮留辮是清朝的高壓手段；推崇儒學、厚待科舉屬於懷柔。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-11", "no": 11, "c": "d8", "src": "考卷 114上翰林社會2上A卷 卷5 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "張老師到德國旅行，參觀德國皇城中的茶室。領隊介紹說：「17、18 世紀時，歐洲宮廷喜歡將各式各樣的青花瓷作為室內的裝飾品。」上述城堡中的瓷器若是從製瓷業的專業市鎮製造，應是產自中國何地？", "o": ["杭州", "徽州", "景德鎮", "北京"], "a": 2, "e": "江西景德鎮以製瓷聞名，是明清最有名的瓷器專業市鎮。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-12", "no": 12, "c": "d7", "src": "考卷 114上翰林社會2上A卷 卷5 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "明代為防備倭寇、清初為打擊鄭氏政權都曾實施下列何項政策？", "o": ["渡臺禁令", "海禁政策", "鎖國政策", "劃界封山"], "a": 1, "e": "明代為了防備倭寇、清初為了打擊臺灣鄭氏，都實施海禁政策。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-13", "no": 13, "c": "d5", "src": "考卷 114上翰林社會2上A卷 卷5 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "小呈在某書中看見一段史料如下：「凡外夷者，我朝皆設市舶司以領之。……許帶方物，官設牙行與民貿易，謂之互市。是有貢船，即有互市，非入貢即不許其互市。」上述史料最可能與下列何者相關？", "o": ["邊市貿易", "走私貿易", "朝貢貿易", "開港通商"], "a": 2, "e": "「非入貢即不許其互市」表示一定要先進貢才能貿易，這就是朝貢貿易。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-14", "no": 14, "c": "d3", "src": "考卷 114上翰林社會2上A卷 卷5 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "日治時期，臺灣總督府將纏足、辮髮和吸食鴉片視為臺灣三大陋習，因此明令禁止纏足解髮，違反者處以百圓以下罰金。上述的辮髮是受下列何者習俗的影響？", "o": ["蒙古人", "西藏人", "漢人", "滿人"], "a": 3, "e": "辮髮是滿人的習俗，清朝強迫漢人剃髮留辮。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-15", "no": 15, "c": "d6", "src": "考卷 114上翰林社會2上A卷 卷5 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "15 世紀前期，中國皇帝下令鄭和展開七次大規模的遠洋航海，並留下世界現存最早的航海圖。上述人物出使西洋對後世的歷史發展有何影響？", "o": ["陸上絲路的興起", "討平倭寇的入侵", "美洲新作物的導入", "各國紛紛前來中國貿易"], "a": 3, "e": "鄭和下西洋宣揚國威，使各國紛紛派使節來中國朝貢、貿易。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-zhenghe"], "chk": ""}, {"id": "h4-16", "no": 16, "c": "d2", "src": "考卷 114上翰林社會2上A卷 卷5 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "歷史老師提問：「何者是促成明代衰亡的原因？」下列哪一位同學的回答錯誤？", "o": ["倭寇嚴重", "滿洲威脅", "西洋人入侵", "流寇之禍"], "a": 2, "e": "明代衰亡的原因有倭寇、滿洲、流寇；西洋人入侵是清代後期的事。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-17", "no": 17, "c": "d3", "src": "考卷 114上翰林社會2上A卷 卷5 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "湘綾在歷史課本上看見了一張疆域圖，如圖(二)。由其版圖輪廓可判斷，此圖可呈現出哪一民族的擴張？", "o": ["契丹", "女真", "突厥", "蒙古"], "a": 1, "e": "圖中的版圖包含新疆、西藏、蒙古，是清代版圖；清朝由女真（滿洲）建立。", "rep": true, "img": "h4-q17", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-18", "no": 18, "c": "d1", "src": "考卷 114上翰林社會2上A卷 卷5 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "「自宋明亡，北方外族入主中原，百年不到，天下大亂。我本是平民，被眾人推舉，率軍攻占金陵（今南京），再北上驅逐韃虜。色目等雖為異族，但若衷心歸順，仍是中華子民。」上文最可能是下列何人的自述？", "o": ["鄭和", "朱元璋", "李自成", "吳三桂"], "a": 1, "e": "平民出身、攻占金陵（南京）、北上驅逐蒙古的是朱元璋。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-19", "no": 19, "c": "d3", "src": "考卷 114上翰林社會2上A卷 卷5 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "「1636 年，把國號大金改『大清』，並改族名為滿洲。可能是因為歷史上女真族建立的金曾滅北宋，為了消除漢人的負面印象才有這樣的作法。」上文記載的是哪一民族的事蹟？", "o": ["蒙古", "突厥", "女真", "契丹"], "a": 2, "e": "1636 年皇太極改國號為「大清」、改族名為滿洲，他們是女真族。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-20", "no": 20, "c": "d11", "src": "考卷 114上翰林社會2上A卷 卷5 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "紀錄片《東方西儒——利瑪竇》結合戲劇演出及紀實，忠實呈現了首位進入中國的耶穌會士利瑪竇神父的生平，此片可讓同信仰的朋友認識該人物的傳教貢獻及促進中西文化交流之功。上述傳教士傳播的是下列哪一宗教？", "o": ["佛教", "猶太教", "天主教", "伊斯蘭教"], "a": 2, "e": "利瑪竇是耶穌會士，傳播的是天主教。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-21", "no": 21, "c": "d4", "src": "考卷 114上翰林社會2上A卷 卷5 題組 (一) 1", "st": "考卷", "ctx": "", "fig": "", "q": "避暑山莊又稱熱河行宮，興建於康熙年間，是中國古代皇家園林中占地最廣，更是目前保存最為完好的皇家行宮。每年 5～9 月間，皇帝暫住山莊避暑，並接見蒙藏活佛與王公貴族，外國使節也因皇帝暫住山莊而前赴接見，避暑山莊在帝國的地位，已成為紫禁城之外，帝國的第二政治中心。興建上述山莊的是下列哪一政權？", "o": ["宋", "元", "明", "清"], "a": 3, "e": "避暑山莊興建於清朝康熙年間。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-qing"], "chk": ""}, {"id": "h4-22", "no": 22, "c": "d1", "src": "考卷 114上翰林社會2上A卷 卷5 題組 (一) 2", "st": "考卷", "ctx": "避暑山莊又稱熱河行宮，興建於康熙年間，是中國古代皇家園林中占地最廣，更是目前保存最為完好的皇家行宮。每年 5～9 月間，皇帝暫住山莊避暑，並接見蒙藏活佛與王公貴族，外國使節也因皇帝暫住山莊而前赴接見，避暑山莊在帝國的地位，已成為紫禁城之外，帝國的第二政治中心。興建上述山莊的是下列哪一政權？", "fig": "", "q": "上文中帝國的首要政治中心在圖(三)中何地？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "清帝國的首要政治中心是北京，在圖中北方的甲。", "rep": false, "img": "h4-q22", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-23", "no": 23, "c": "d6", "src": "考卷 114上翰林社會2上A卷 卷5 題組 (二) 3", "st": "考卷", "ctx": "", "fig": "", "q": "國立臺灣歷史博物館舉辦「鄭和與海洋文化——鄭和下西洋六百周年特展」。展出內容分為鄭和下西洋史跡、海上絲路及古代航海科技三大主題，展出物品包括鄭和船隊「寶船」模型、木刻塗金的「天妃坐像」及比利時國家海洋博物館提供的十艘中國船模。上述的西洋指的是圖(四)中何地？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "鄭和下西洋的「西洋」指東南亞、印度洋一帶，圖中位在亞洲南方、非洲和澳洲之間的是乙（印度洋）。", "rep": true, "img": "h4-q23", "imgnote": "", "fh": "", "maps": ["h4-zhenghe"], "chk": ""}, {"id": "h4-24", "no": 24, "c": "d6", "src": "考卷 114上翰林社會2上A卷 卷5 題組 (二) 4", "st": "考卷", "ctx": "國立臺灣歷史博物館舉辦「鄭和與海洋文化——鄭和下西洋六百周年特展」。展出內容分為鄭和下西洋史跡、海上絲路及古代航海科技三大主題，展出物品包括鄭和船隊「寶船」模型、木刻塗金的「天妃坐像」及比利時國家海洋博物館提供的十艘中國船模。上述的西洋指的是圖(四)中何地？", "fig": "", "q": "承上題，上述航海行動奠定華人在下列何地的發展基礎？", "o": ["琉球", "朝鮮", "日本", "東南亞"], "a": 3, "e": "鄭和下西洋後，東南沿海居民大量移居東南亞，奠定了南洋華人社會的基礎。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-zhenghe"], "chk": ""}, {"id": "h4-25", "no": 25, "c": "d11", "src": "考卷 114上翰林社會2上A卷 卷5 進階思考題 1", "st": "考卷", "ctx": "", "fig": "", "q": "明末清初西方傳教士陸續來到中國，並且將西方的近代科技傳入中國，促進中西文化交流，當時傳入的西方科技不包括下列何者？", "o": ["天文曆法", "《幾何原本》", "海上導航的指南針", "畫有經緯線的地圖"], "a": 2, "e": "指南針是中國宋代的發明，不是傳教士傳入的西方科技。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-26", "no": 26, "c": "d3", "src": "考卷 114上翰林社會2上A卷 卷5 進階思考題 2", "st": "考卷", "ctx": "", "fig": "", "q": "歷史課堂時，老師要同學以「北魏、元帝國、清帝國」進行比較，下列哪位同學的說法最正確？", "o": ["均厲行漢化政策", "將人民分為四等級", "初實施科舉取士", "皆統治者為外族"], "a": 3, "e": "北魏（鮮卑）、元（蒙古）、清（滿）的統治者都是外族。只有元朝把人民分四等；厲行漢化的是北魏。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-27", "no": 27, "c": "d14", "src": "考卷 114上翰林社會2上A卷 卷5 進階思考題 3", "st": "考卷", "ctx": "", "fig": "", "q": "中國的經濟週期通常與王朝的興衰相互對應，經歷清軍入關等政治、戰爭、人口遷徙、工商及海陸交通的發展而不斷改變。老師請問明清時期的經濟發展進行討論，下列哪一位同學的說法不正確？", "o": ["景德鎮等專業市鎮興起", "引進美洲作物，減緩糧食不足", "因廢除坊市制限制，住商分立", "市面常以白銀與銅錢並用"], "a": 2, "e": "廢除坊市制度是宋代的事，不是明清。專業市鎮、美洲作物、白銀與銅錢並用都是明清的經濟特色。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-28", "no": 28, "c": "d9", "src": "考卷 114上翰林社會2上A卷 卷5 進階思考題 4", "st": "考卷", "ctx": "", "fig": "", "q": "許文是明末的平民百姓，他可能有下列哪一種生活經歷？", "o": ["跟隨鄭和出使西洋", "聽到首都被攻陷南京", "靠吃番薯等作物果腹", "熟讀《幾何原本》參加科舉"], "a": 2, "e": "明末已經引進番薯等美洲作物。鄭和是明初的人；明末首都是北京；《幾何原本》不是科舉考試的內容。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-29", "no": 29, "c": "d5", "src": "考卷 114上翰林社會2上A卷 卷5 進階思考題 5", "st": "考卷", "ctx": "", "fig": "", "q": "明清時期東亞世界大致在朝貢貿易體制下進行互動，隨著大航海時代的來臨，西方商人與傳教士東來，東西方的商貿往來和文化交流日益密切。歷史讀書會中，幾位同學探討清帝國初期的中外貿易發展，哪位同學的說法需要修正？", "o": ["康熙皇帝曾嚴格廢除開海政策", "當時的對外貿易主要以朝貢貿易為主", "主要使用白銀與銅錢交易", "昔在泉州、泉港設立市舶司"], "a": 3, "e": "清初對外以朝貢貿易為主、使用白銀與銅錢，也曾實施海禁；在泉州設市舶司是宋元時期的事，所以 (D) 需要修正。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "選項"}, {"id": "h4-30", "no": 30, "c": "d7", "src": "考卷 114上翰林社會2上A卷 卷5 進階思考題 6", "st": "考卷", "ctx": "", "fig": "", "q": "大雄是清初的福建商人，海上貿易帶來了許多財富，他不可能有下列哪一種生活經驗？", "o": ["逛夜市以白銀買烤玉米", "透過朝貢貿易與外國往來", "與同鄉商人集成專業市鎮", "因政府打擊鄭氏而無法出海貿易"], "a": 1, "e": "朝貢貿易是官方的，清初福建的民間商人不可能透過朝貢貿易往來；還可能因為打擊鄭氏的海禁而無法出海。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-31", "no": 31, "c": "d11", "src": "考卷 114上翰林社會2上A卷 卷5 進階思考題 7", "st": "考卷", "ctx": "", "fig": "", "q": "書播在看電視劇情時，看到劇情中的統治者要求受統治的人民配合習俗薙髮留辮，以表示臣服。根據上述劇情判斷，劇中出現下列哪一場景才符合史實？", "o": ["官員與耶穌會傳教士會面", "配合改漢姓、禁胡語", "鄭和奉命七次下西洋", "以紙幣為主要貨幣"], "a": 0, "e": "薙髮留辮是清朝。清初有耶穌會士在朝廷任職（例如湯若望），官員與傳教士會面符合史實。改漢姓是北魏；鄭和是明初；紙幣是宋元。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-32", "no": 32, "c": "d11", "src": "考卷 114上翰林社會2上A卷 卷6 第 1 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "耶穌會周邦強神父在大學演講〈利瑪竇：友誼、對話和平的遺產〉專案會議，向聞名於世的傳教士利瑪竇致敬，該傳教士被明朝士大夫尊稱為「泰西儒士」。上述人物奠定下列哪一宗教在中國發展的基礎？", "o": ["佛教", "基督教", "天主教", "伊斯蘭教"], "a": 2, "e": "利瑪竇是天主教耶穌會士，奠定了天主教在中國發展的基礎。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-33", "no": 33, "c": "d6", "src": "考卷 114上翰林社會2上A卷 卷6 第 5 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "三寶太監是明朝著名的航海家，奉明成祖之命出使，其主要目的是在宣揚國威。他因看重貿易利益，紛紛遣使進貢。上述航海家的足跡遍及圖(三)中何地？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "三寶太監鄭和的船隊航行到印度洋，在圖中是丁（孟加拉灣一帶）。", "rep": false, "img": "h4-q33", "imgnote": "", "fh": "", "maps": ["h4-zhenghe"], "chk": ""}, {"id": "h4-34", "no": 34, "c": "d10", "src": "考卷 114上翰林社會2上A卷 卷6 第 7 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "2013 年中國提出「一帶一路」，先後發表了「絲綢之路經濟帶」與「21 世紀海上絲綢之路」的構想。回顧中國歷史，15 世紀末，歐洲國家發現通往亞洲的新航路，透過亞洲殖民據點的轉運，大量購買中國商品。上述提到的歐洲國家主要為下列何者？", "o": ["英國、法國", "英國、荷蘭", "荷蘭、法國", "西班牙、葡萄牙"], "a": 3, "e": "15 世紀末開闢新航路、到亞洲大量購買中國商品的主要是西班牙、葡萄牙。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-global"], "chk": ""}, {"id": "h4-35", "no": 35, "c": "d4", "src": "考卷 114上翰林社會2上A卷 卷6 第 9 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "2025 年初，西藏日喀則市發生規模 6.8 的地震，震災區海拔 4,300 公尺，晚上零下 10 幾度，高海拔地區缺氧，救援困難。該地區於下列何時納入中國版圖？", "o": ["唐代", "宋代", "明代", "清代"], "a": 3, "e": "西藏是在清代納入中國版圖的。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-qing"], "chk": ""}, {"id": "h4-36", "no": 36, "c": "d7", "src": "考卷 114上翰林社會2上A卷 卷6 第 11 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "下列為中國某個朝代後期的商貿情況敘述，根據內容判斷，此一朝代最可能為何？「部分商人聚集在東南沿海從事貿易活動，運送絲、茶或瓷器等商品到海外販售，賺取白銀，途中須躲避官府的查緝；海盜的劫掠，必要時甚至會進行海盜行為。」", "o": ["唐代", "宋代", "元代", "明代"], "a": 3, "e": "東南沿海商人走私絲、茶、瓷器換取白銀，還要躲避官府查緝（海禁），這是明代後期的情形。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-37", "no": 37, "c": "d2", "src": "考卷 114上翰林社會2上A卷 卷6 第 12 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)是明形記下了歷史課時，老師口述的重點。根據圖中內容判斷，老師講述的是下列何人的事蹟？「他在明朝滅亡後，引清兵入關，與清軍合作剿滅流寇、明朝勢力，為清朝統治奠下基礎。」", "o": ["利瑪竇", "鄭和", "吳三桂", "張擇端"], "a": 2, "e": "明朝滅亡後引清兵入關、和清軍合作剿滅流寇的是吳三桂。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-38", "no": 38, "c": "d14", "src": "考卷 114上翰林社會2上A卷 卷6 第 13 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "歷史老師要同學討論有關明末的內憂外患，哪一位同學的說法不正確？", "o": ["倭寇騷擾", "連年饑荒", "外族西夏", "滿清進犯"], "a": 2, "e": "明末的內憂外患有倭寇、饑荒與流寇、滿清；西夏是宋代的外患。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-39", "no": 39, "c": "d2", "src": "考卷 114上翰林社會2上A卷 卷6 第 14 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "明帝國末代皇帝明思宗於煤山自縊殉國，自殺之前，他拿劍砍下長平公主的左臂，這位長平公主後來成為金庸小說《鹿鼎記》中「獨臂神尼」的參考原型。明思宗遭逢的是哪一場亡國之禍？", "o": ["滿清入關", "靖康之禍", "遼軍南侵", "流寇之亂"], "a": 3, "e": "崇禎帝是因為李自成的流寇攻陷北京而自縊。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-40", "no": 40, "c": "d13", "src": "考卷 114上翰林社會2上A卷 卷6 第 16 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "日本閉關自守時期，歐洲人只能在長崎的出島與日本進行貿易，與一般民眾隔絕。但是，歐洲人帶來的望遠鏡等知識技術，仍進入庶民的生活中。上述的「歐洲人」指的是下列何者？", "o": ["英國人", "荷蘭人", "西班牙人", "葡萄牙人"], "a": 1, "e": "日本鎖國時只准荷蘭人（和中國人）在長崎出島貿易。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-41", "no": 41, "c": "d6", "src": "考卷 114上翰林社會2上A卷 卷6 第 18 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "曾有記者專程遠赴鄭和的故鄉雲南晉寧縣採訪，不僅參觀鄭和紀念館、鄭和故里遺跡，還特別採訪鄭和第 18 代孫，鄭和雖然是宦官，但其長兄把長子過繼給鄭和，子孫代代相傳，總數約有 400 多人。上述這位歷史人物有何貢獻？", "o": ["出使西洋", "北伐蒙古", "平定流寇", "討平倭寇"], "a": 0, "e": "鄭和最大的貢獻是七次出使西洋。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-zhenghe"], "chk": ""}, {"id": "h4-42", "no": 42, "c": "d11", "src": "考卷 114上翰林社會2上A卷 卷6 進階思考題 2（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "顏英在整理明清歷史筆記時，內容錯誤連連，只有下列哪一項正確？", "o": ["李自成引清兵入關", "徐光啟改都北京，明亡", "吳三桂率領艦隊出使西洋", "利瑪竇容許中國教徒祭祖、祭孔"], "a": 3, "e": "利瑪竇容許中國教徒祭祖、祭孔，正確。引清兵入關的是吳三桂；遷都北京的是明成祖；出使西洋的是鄭和。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-43", "no": 43, "c": "d8", "src": "考卷 114上翰林社會2上A卷 卷6 進階思考題 3（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "永慶是清乾隆年間的商人，他可能比宋代的商人擁有下列哪一項優越的條件？", "o": ["可以在夜市經營商業", "使用銅錢作為交易媒介", "可至廣州進行海外貿易", "可至專業市鎮採購商品"], "a": 3, "e": "專業市鎮是明清才興起的。夜市、使用銅錢、在廣州進行海外貿易，宋代就有了。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-44", "no": 44, "c": "d3", "src": "考卷 114上翰林社會2上A卷 卷6 進階思考題 4（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "是星參加電視台「盛清風雲」話劇演出，飾演一位住在杭州的士人，若話劇內容須合於史實，下列何者最可能是在他劇中的生活情況？", "o": ["通過科舉考試，晉身為世族", "因文章內容批評朝政遭到誅殺", "屬於南人階級，社會地位低落", "響應朝廷號召，跟隨鄭和到西洋"], "a": 1, "e": "清代大興文字獄，文人可能因為文章批評朝政而被殺。世族是魏晉；南人是元代；鄭和是明初。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-45", "no": 45, "c": "d14", "src": "考卷 114上翰林社會2上A卷 卷6 進階思考題 6（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "顏誠是兩宋時期住在首都的平民百姓，他最可能有用下列哪一生活經歷？", "o": ["到夜市享受地方美食", "聽聞契丹人攻陷汴京", "研讀《幾何原本》準備科舉考試", "拿著白銀上街購買日常用品"], "a": 0, "e": "宋代坊市制度瓦解，已經有夜市。汴京是被女真攻陷；《幾何原本》是明末才翻譯；白銀成為主要貨幣是明代以後。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-46", "no": 46, "c": "d5", "src": "考卷 114上翰林社會2上B卷 卷5 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "小安是生活在 15 世紀前期的南洋居民，某日他跟隨番國家的使節前往傳說中的「天朝」，將國家的奇珍異寶獻給天朝的皇帝後，接受冊封並在天朝境內進行商業買賣。上述互動應為下列何項政策？", "o": ["朝貢貿易", "海禁政策", "和親政策", "羈縻制度"], "a": 0, "e": "接受冊封、獻上貢品後才能在中國進行買賣，就是朝貢貿易。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-47", "no": 47, "c": "d4", "src": "考卷 114上翰林社會2上B卷 卷5 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列兩份資料的統治者，應為哪一政權？\n資料一：新疆在 18 世紀時，統治者平定當地後逐漸加深控制，並以「新的疆土」之稱於當地設省。\n資料二：西藏以前有圖博、吐蕃等稱呼，直到 18 世紀時，統治者平定當地起事，逐漸納入版圖，並更名為西藏。", "o": ["唐朝", "元朝", "明朝", "清朝"], "a": 3, "e": "18 世紀平定新疆、西藏並納入版圖的是清朝。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-qing"], "chk": ""}, {"id": "h4-48", "no": 48, "c": "d1", "src": "考卷 114上翰林社會2上B卷 卷5 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "下表為明代軍費與年度支出的統計表，下列何者不是導致軍費支出日益增加的原因？", "o": ["蒙古侵擾北方", "女真人的進犯", "倭寇騷擾沿海", "西方列強侵略"], "a": 3, "e": "明代軍費增加是因為蒙古、女真、倭寇；西方列強侵略是清代後期的事。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-49", "no": 49, "c": "d3", "src": "考卷 114上翰林社會2上B卷 卷5 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "在歷史上，明末清初的吳梅村一句「慟哭六軍俱縞素，衝冠一怒為紅顏」，說明了明代山海關守將何人降清，引清兵入關？", "o": ["鄭和", "吳三桂", "徐光啟", "李自成"], "a": 1, "e": "「衝冠一怒為紅顏」說的是山海關守將吳三桂降清、引清兵入關。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-50", "no": 50, "c": "d3", "src": "考卷 114上翰林社會2上B卷 卷5 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "阿青是一位生活在明代北京的雜貨商人，他最不可能有下列哪一經歷？", "o": ["在市場販售馬鈴薯", "到專業市鎮購買商品", "轉手景德鎮青花瓷盤", "被官府要求薙髮留辮"], "a": 3, "e": "薙髮留辮是清朝的政策，明代的商人不會遇到。馬鈴薯、專業市鎮、景德鎮瓷器在明代都有。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-51", "no": 51, "c": "d1", "src": "考卷 114上翰林社會2上B卷 卷5 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "元代末年，群雄並起，最後以出身民間而建立明代的是下列何人？", "o": ["吳三桂", "朱元璋", "李自成", "鐵木真"], "a": 1, "e": "元末群雄並起，平民出身、最後建立明朝的是朱元璋。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-52", "no": 52, "c": "d1", "src": "考卷 114上翰林社會2上B卷 卷5 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "明代自建國以後，北方始終處於「甲」的威脅之下，而東南沿海則苦於「乙」的侵擾。甲、乙依序應填入下列何者？", "o": ["突厥、流寇", "蒙古、倭寇", "女真、倭寇", "契丹、流寇"], "a": 1, "e": "明代北方一直受到蒙古威脅，東南沿海則苦於倭寇侵擾。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-53", "no": 53, "c": "d11", "src": "考卷 114上翰林社會2上B卷 卷5 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "18 世紀時，當時歐洲的學者因為崇尚中國儒家風氣，改編了中國傳統民間故事。根據上述內容判斷，歐洲人接觸到中國儒家風氣，應與何種因素有關？", "o": ["耶穌會傳教士訪華後交流經典", "蒙古西征將經典帶入歐洲", "鄭和下西洋時歐洲人有貿易", "阿拉伯商人經商時帶回的經典"], "a": 0, "e": "耶穌會傳教士把儒家經典帶回歐洲，歐洲人因此接觸到儒家思想。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-54", "no": 54, "c": "d11", "src": "考卷 114上翰林社會2上B卷 卷5 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "某書為中國士大夫徐光啟與傳教士共同翻譯的歐洲典籍，成為當時中國人學習數學的教材。該典籍應為下列何者？", "o": ["《聖經》", "《四書集注》", "《回回藥方》", "《幾何原本》"], "a": 3, "e": "徐光啟與利瑪竇合譯的是《幾何原本》。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-55", "no": 55, "c": "d3", "src": "考卷 114上翰林社會2上B卷 卷5 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列兩則事例反映出明清時期的哪一現象？\n事例一：明太祖年間，官員趙伯寧上〈萬言書〉，其中有「妻子孫而作則」，句，因「作則」與「作賊」音似，遭處死。\n事例二：清世宗年間，徐駿因寫了「清風不識字，何故亂翻書」的詩句，朝廷認為譏諷大清，被處死。", "o": ["禁止私人講學論政", "重武輕文貶低儒生", "以文字獄羅織文人", "科舉取士出現弊端"], "a": 2, "e": "兩則事例都是因為詩文裡的字句被處死，這是文字獄。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-56", "no": 56, "c": "d10", "src": "考卷 114上翰林社會2上B卷 卷5 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "15、16 世紀，歐洲商人到東亞貿易，他們帶著口口大量購買中國的絲綢、瓷器等商品，造成中國貨幣經濟產生重大變化。上文提到的口口應為下列何者？", "o": ["白銀", "黃金", "青銅", "紙幣"], "a": 0, "e": "歐洲商人帶著白銀來買中國的絲綢、瓷器，白銀大量流入中國。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-global"], "chk": ""}, {"id": "h4-57", "no": 57, "c": "d3", "src": "考卷 114上翰林社會2上B卷 卷5 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "同是由來自關外的少數民族所統治，清代國祚卻較蒙古人的元代為長，因為它對漢族並非單純地征服、鎮壓，而是實施一套高壓與懷柔相結合的統治政策。下列哪一政策是屬於懷柔的部分？", "o": ["舉行科舉", "大興文字獄", "採九品任官的方法", "強迫漢人薙髮留辮"], "a": 0, "e": "舉行科舉是懷柔；大興文字獄、薙髮留辮是高壓。九品官人法是魏晉南北朝的制度。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-58", "no": 58, "c": "d13", "src": "考卷 114上翰林社會2上B卷 卷5 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "某部電影內容敘述 17 世紀時，在日本傳教的耶穌會傳教士遭到指控背景下救義。其學生為了證實老師的清白前往日本，但在過程中看到了他們信仰的宗教在日本發展的困境。上述主角等人信仰的宗教，最可能為下列何者？", "o": ["基督教新教", "伊斯蘭教", "天主教", "佛教"], "a": 2, "e": "17 世紀在日本傳教的耶穌會士，信仰的是天主教。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-59", "no": 59, "c": "d7", "src": "考卷 114上翰林社會2上B卷 卷5 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國至唐代以來，海外貿易就相當發達，但明代與清初政府均下令實施海禁政策，嚴禁人民出海。其防堵的對象分別為何？", "o": ["明—流寇，清—倭寇", "明—荷蘭，清—西班牙", "明—倭寇，清—臺灣鄭氏", "明—臺灣鄭氏，清—倭寇"], "a": 2, "e": "明代海禁是為了防倭寇，清初海禁是為了打擊臺灣鄭氏。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-60", "no": 60, "c": "d10", "src": "考卷 114上翰林社會2上B卷 卷5 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "15、16 世紀末，歐洲人發現了通往亞洲的新航路，陸續前來中國進行貿易。明代中葉到清初對外關係的特徵不包括下列何者？", "o": ["對外經濟、文化等交流頻繁", "政府閉關自守禁絕對外貿易", "白銀大量流入逐漸取代紙幣", "交易商品以絲綢、瓷器為主"], "a": 1, "e": "明中葉到清初中外交流頻繁、白銀大量流入，並沒有完全禁絕對外貿易。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-global"], "chk": ""}, {"id": "h4-61", "no": 61, "c": "d11", "src": "考卷 114上翰林社會2上B卷 卷5 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "傳教士來到中國，將西方的科技傳入，並且也將中國典籍、園林建築傳回歐洲，其中的西方科技不包含下列何者？", "o": ["幾何學", "天文曆法", "軍事科技", "活字印刷術"], "a": 3, "e": "活字印刷術是中國北宋畢昇發明的，不是傳教士傳入的西方科技。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-62", "no": 62, "c": "d13", "src": "考卷 114上翰林社會2上B卷 卷5 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "隨著大航海時代來臨，東亞與西方曾有廣泛的文化交流，但後來卻又因故中斷交流，例如：日本在 17 世紀實施鎖國政策，限制通商與傳教，只允許中國、荷蘭商船到何地貿易？", "o": ["東京", "大阪", "京都", "長崎"], "a": 3, "e": "日本鎖國時只開放長崎，讓中國和荷蘭的商船貿易。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-63", "no": 63, "c": "d7", "src": "考卷 114上翰林社會2上B卷 卷5 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "「張老是明代人，(甲)平常聽聞北方蒙古進犯，後來又(乙)聽說不要到東南沿海活動，(丙)因為有流寇在海上劫掠，(丁)白天他跟友人家到夜市逛街，可幸運地買到精緻的景德鎮瓷器，高興地捧著瓷器回家。」上述是峻碩的歷史作業，何者敘述有誤？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "在東南沿海海上劫掠的是倭寇，不是流寇，所以 (丙) 錯誤。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-64", "no": 64, "c": "d9", "src": "考卷 114上翰林社會2上B卷 卷5 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "凱瑜晚餐時，在餐桌上看到花生、玉米、馬鈴薯等食材，想起老師曾提到這些作物原產於美洲，經過東西文化交流，才會出現在我們的餐桌上。關於這些食物的傳播歷程，下列何項敘述正確？", "o": ["荷蘭治臺時引進臺灣，再經由臺灣傳至中國", "鄭和出使「西洋」時，從中南美洲帶回中國", "蒙古三次西征橫跨歐亞，促進異國作物交流", "歐洲人到亞洲貿易，將美洲作物傳入中國"], "a": 3, "e": "美洲作物是歐洲人到亞洲貿易時傳入中國的。鄭和沒有到美洲；蒙古西征時美洲作物還沒傳出美洲。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-global"], "chk": ""}, {"id": "h4-65", "no": 65, "c": "d3", "src": "考卷 114上翰林社會2上B卷 卷5 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "滿清以少數民族作為統治者，針對不同的民族實行多元的統治政策，其中何者並非針對統治漢人所採取的策略？", "o": ["大興文字獄，箝制其思想", "保護支持其宗教藉以拉攏", "舉行科舉，特別借用士人", "強迫兩族人都要薙髮留辮"], "a": 1, "e": "保護支持宗教（藏傳佛教）是用來拉攏蒙古、西藏的，不是針對漢人的策略。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-66", "no": 66, "c": "d5", "src": "考卷 114上翰林社會2上B卷 卷5 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "佑軒以「明清時期的對外貿易」為主題，撰寫歷史報告，下列哪一項資料會出現在他的報告中？", "o": ["明代政府首次設立市舶司，管理海上貿易", "對外貿易使用的貨幣，是紙幣與銀錢並用", "實施海禁，以「朝貢貿易」進行對外貿易", "15 世紀初期，出現「海商集團」影響貿易"], "a": 2, "e": "明清實施海禁，對外貿易以朝貢貿易為主。市舶司唐代就有；明清是白銀與銅錢並用；海商集團是 16 世紀以後才活躍。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-67", "no": 67, "c": "d12", "src": "考卷 114上翰林社會2上B卷 卷5 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "明清之際，西方文物大量傳入中國，而中國思想與技術也傳至西方，這樣的文化交流，因清代發生哪一事件而被迫中斷？", "o": ["厲行海禁政策，阻止外人入境", "大興文字獄，排斥西學與洋教", "實施禁教，驅逐西方的傳教士", "積極經營西域，防止歐人東進"], "a": 2, "e": "清朝雍正實施禁教、驅逐傳教士，中西文化交流被迫中斷。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-68", "no": 68, "c": "d6", "src": "考卷 114上翰林社會2上B卷 卷5 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "15 世紀末，葡萄牙人發現了經由非洲南端通往亞洲的新航路，引發地理大發現的風潮，對世界各地的歷史發展產生重大影響。下列何者並非此風潮對中國造成的影響？", "o": ["鄭和奉艦隊多次出使西洋", "西方的近代科技傳入中國", "白銀自海外大量輸入中國", "天主教耶穌會傳教士來華"], "a": 0, "e": "鄭和下西洋在 15 世紀初，比新航路開闢還早，不是新航路帶來的影響。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-zhenghe"], "chk": ""}, {"id": "h4-69", "no": 69, "c": "d2", "src": "考卷 114上翰林社會2上B卷 卷5 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "「1980 年在北京永定門外沙子口一個建築工地上，施工者掘到古錢一枚，其銅色金黃，寬輪光背，『永昌通寶』4 個字清晰可辨。考古學者判斷，此幣應為明末農民起義軍領袖李自成所鑄。」下列何者與該位領袖最為相關？", "o": ["帶領流寇攻陷北京，明代亡", "驅除蒙古人，結束元朝統治", "其武裝力量的海商，進行東亞走私貿易", "與吳三桂合作，攻陷北京，遂自立為王"], "a": 0, "e": "李自成帶領流寇攻陷北京，明朝滅亡。驅逐蒙古的是朱元璋；和清軍合作的是吳三桂。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-70", "no": 70, "c": "d3", "src": "考卷 114上翰林社會2上B卷 卷5 題組 (一) 1", "st": "考卷", "ctx": "", "fig": "", "q": "「雍正王朝」這部歷史劇以正史的拍播手法，描寫諸皇子間的鬥爭、輾轉。雍正脫穎而出，以及雍正即位後，在壓制中大力推動改革，最後勞累而死的過程。該劇創下極高收視率，一改過往雍正的電視反派形象，甚至讓許多觀眾開始研究這段歷史。上文中的故事背景，是由哪一民族所建立的朝代？", "o": ["契丹", "匈奴", "女真", "蒙古"], "a": 2, "e": "雍正是清朝皇帝，清朝由女真（滿洲）建立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-71", "no": 71, "c": "d12", "src": "考卷 114上翰林社會2上B卷 卷5 題組 (一) 2", "st": "考卷", "ctx": "「雍正王朝」這部歷史劇以正史的拍播手法，描寫諸皇子間的鬥爭、輾轉。雍正脫穎而出，以及雍正即位後，在壓制中大力推動改革，最後勞累而死的過程。該劇創下極高收視率，一改過往雍正的電視反派形象，甚至讓許多觀眾開始研究這段歷史。", "fig": "", "q": "承上題，雍正在經歷繼承權之爭後登基，立即下令禁教，這與下列哪一原因最密切相關？", "o": ["耶穌會允許教徒祭祖", "傳教士涉及宮廷政爭", "儒家經典被傳到歐洲", "傳教士拒絕薙髮留辮"], "a": 1, "e": "雍正禁教主要是因為傳教士涉入宮廷皇位繼承的政爭。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-72", "no": 72, "c": "d3", "src": "考卷 114上翰林社會2上B卷 卷5 題組 (一) 3", "st": "考卷", "ctx": "「雍正王朝」這部歷史劇以正史的拍播手法，描寫諸皇子間的鬥爭、輾轉。雍正脫穎而出，以及雍正即位後，在壓制中大力推動改革，最後勞累而死的過程。該劇創下極高收視率，一改過往雍正的電視反派形象，甚至讓許多觀眾開始研究這段歷史。", "fig": "", "q": "根據上文，在觀看這部連續劇時，最可能會看到下列哪一場景？", "o": ["派施琅攻臺並將臺灣納入版圖", "文人的詩句因得罪皇帝被判刑", "李自成起事，皇帝出兵平定", "皇帝為了穩固政權遷都至北京"], "a": 1, "e": "雍正時大興文字獄，劇中可能看到文人因詩句得罪皇帝被判刑。攻臺是康熙；遷都北京是明成祖。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-73", "no": 73, "c": "d6", "src": "考卷 114上翰林社會2上B卷 卷5 題組 (二) 4", "st": "考卷", "ctx": "", "fig": "", "q": "附圖是 15 世紀初期，鄭和下西洋的航海路線圖，是歷時 29 年的七場連續的大規模遠洋航海，象徵著中國航海史上的一個高峰。圖中的航行路線主要是發生於哪位皇帝在位時？", "o": ["漢武帝", "唐太宗", "宋真宗", "明成祖"], "a": 3, "e": "派鄭和下西洋的是明成祖。", "rep": true, "img": "h4-zhenghe", "imgnote": "附圖以課本〈鄭和下西洋路線圖〉代替", "fh": "", "maps": [], "chk": ""}, {"id": "h4-74", "no": 74, "c": "d6", "src": "考卷 114上翰林社會2上B卷 卷5 題組 (二) 5", "st": "考卷", "ctx": "", "fig": "", "q": "由附圖判斷，鄭和下西洋的「西洋」是指今日哪些地區？", "o": ["東南亞、大西洋", "大西洋、印度洋", "東南亞、印度洋", "太平洋、大西洋"], "a": 2, "e": "「西洋」指今日的東南亞、印度洋一帶。", "rep": false, "img": "h4-zhenghe", "imgnote": "附圖以課本〈鄭和下西洋路線圖〉代替", "fh": "", "maps": [], "chk": ""}, {"id": "h4-75", "no": 75, "c": "d6", "src": "考卷 114上翰林社會2上B卷 卷5 題組 (二) 6", "st": "考卷", "ctx": "", "fig": "", "q": "由附圖包含歷次出使的艦隊航行範圍，可知其航行路線最遠抵達何地？", "o": ["美洲西岸", "印度南岸", "歐洲西部", "非洲東岸"], "a": 3, "e": "鄭和的船隊最遠到達非洲東岸。", "rep": false, "img": "h4-zhenghe", "imgnote": "附圖以課本〈鄭和下西洋路線圖〉代替", "fh": "", "maps": [], "chk": ""}, {"id": "h4-76", "no": 76, "c": "d6", "src": "考卷 114上翰林社會2上B卷 卷5 題組 (二) 7", "st": "考卷", "ctx": "", "fig": "", "q": "此大規模的航海活動影響深遠，下列何者不是其所造成的影響？", "o": ["沿海居民移居東南亞", "明代向南方擴展版圖", "南洋諸國向明帝國進貢", "擴大了朝貢貿易的規模"], "a": 1, "e": "鄭和下西洋是為了宣揚國威、擴大朝貢，並沒有向南擴展版圖。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-zhenghe"], "chk": ""}, {"id": "h4-77", "no": 77, "c": "d6", "src": "考卷 114上翰林社會2上B卷 卷6 第 4 題（跨課）", "st": "考卷", "ctx": "", "fig": "圖(一)：一條從中國東南沿海出發，經南海、麻六甲海峽，到達印度洋沿岸與非洲東岸的航線圖。", "q": "歷史老師為了增進同學解讀歷史圖表的能力，以圖(一)來說明，由圖中內容判斷，老師講解的主題最可能為下列何者？", "o": ["鄭和艦隊出使西洋路線圖", "明代中後期流寇活動區域圖", "蒙古西征路線及元代疆域圖", "15 世紀歐洲人貿易路線圖"], "a": 0, "e": "從中國東南沿海出發，經南海到印度洋與非洲東岸，是鄭和下西洋的航線。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-78", "no": 78, "c": "d3", "src": "考卷 114上翰林社會2上B卷 卷6 第 6 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "清代為鞏固政權，採取高壓與懷柔並行的統治政策。清代實施高壓政治箝制漢人所使用的手段，不包括下列何者？", "o": ["消滅反清勢力", "強迫薙髮留辮", "廢除科舉考試", "大興文字獄"], "a": 2, "e": "清朝照常舉行科舉（懷柔政策），並沒有廢除科舉。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-79", "no": 79, "c": "d12", "src": "考卷 114上翰林社會2上B卷 卷6 第 7 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "隨著大航海時代來臨，明末清初來華的傳教士對中西文化交流貢獻極大，但清代哪一位皇帝因傳教士涉及宮廷政爭而將傳教士逐出中國？", "o": ["康熙皇帝", "雍正皇帝", "明太祖", "明成祖"], "a": 1, "e": "雍正因為傳教士涉及宮廷政爭，下令禁教、將傳教士逐出中國。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-81", "no": 81, "c": "d13", "src": "考卷 114上翰林社會2上B卷 卷6 第 9 題（跨課）", "st": "考卷", "ctx": "", "fig": "圖(三)閱讀卡片", "q": "莉亞進行歷史的閱讀活動時看到了圖(三)的卡片，根據圖片內容判斷，「甲國」應為下列何者？「時間：17 世紀；地點：日本；背景：政府下令實施鎖國政策，除了中或和「甲國」以外，其餘國家不得與日本交流。」", "o": ["荷蘭", "英國", "西班牙", "葡萄牙"], "a": 0, "e": "日本鎖國時，除了中國之外只准荷蘭交流。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-82", "no": 82, "c": "d10", "src": "考卷 114上翰林社會2上B卷 卷6 第 10 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "明朝初年貨幣原以紙幣為主，後來卻因對外貿易長期出超，中國境內流通的貨幣大受影響，而形成了下列哪一種貨幣制度？", "o": ["白銀與銅錢並用", "白銀與紙幣並用", "紙幣與銅錢並用", "黃金與銅錢並用"], "a": 0, "e": "對外貿易長期出超，白銀大量流入，形成白銀與銅錢並用的制度。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-global"], "chk": ""}, {"id": "h4-83", "no": 83, "c": "d2", "src": "考卷 114上翰林社會2上B卷 卷6 第 11 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "民亂的發生大多是因為「官逼民反」，主政者實應負起相當大的責任。下列哪一動亂可為上述的佐證？", "o": ["靖康之禍", "倭寇之患", "永嘉之禍", "流寇之亂"], "a": 3, "e": "明末天災加上官府重稅，災民被逼成為流寇，最能說明「官逼民反」。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-84", "no": 84, "c": "d5", "src": "考卷 114上翰林社會2上B卷 卷6 第 12 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "在歷史上中國曾經強烈自認是「天朝大國」，透過冊封的方式，建立以中國為中心的朝貢貿易體制。上述發生在哪一時段？", "o": ["秦漢", "隋唐", "宋元", "明清"], "a": 3, "e": "明清以天朝自居，透過冊封建立以中國為中心的朝貢體制。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-85", "no": 85, "c": "d11", "src": "考卷 114上翰林社會2上B卷 卷6 第 20 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "《坤輿萬國全圖》為中國第一幅具有完整經緯度的地圖，象徵著中西雙方世界在科學接觸後出現的成果。上述地圖的出現，是因為下列何者的影響？", "o": ["利瑪竇", "畢昇", "張騫", "鄭和"], "a": 0, "e": "利瑪竇繪製《坤輿萬國全圖》，把有經緯線的西方地理知識帶進中國。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-86", "no": 86, "c": "d12", "src": "考卷 114上翰林社會2上B卷 卷6 第 24 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "明末清初，耶穌會傳教士來華傳入西學，並把中國文物帶回歐洲，這段文化交流對中西方歷史皆有深遠影響，下列相關敘述哪一項與史實不符？", "o": ["利瑪竇影響最大，他容許中國教徒祭祖、祭孔", "西方的地理學、數學和軍事科技外部傳入中國", "中國的儒家經典和庭園藝術等，亦傳入歐洲", "乾隆皇帝下令禁教，中西文化交流因此中斷"], "a": 3, "e": "下令禁教的是雍正，不是乾隆，所以 (D) 與史實不符。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-87", "no": 87, "c": "d7", "src": "考卷 114上翰林社會2上B卷 卷6 題組 (二) 4（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "小櫻在圖書館看到了歷史人物傳記的介紹如下：「戚繼光為 16 世紀明等著名的中國軍人軍事家。白幼年起就對於軍事的研究和學習非常熱衷，之後協助首都北京的防守並陸續平定北方民族的侵擾，受到中央的注目。然而，國家的外患不只陸上，即使中央頒布政策保護居民的安全，海上的外敵侵擾也頻繁發生。戚繼光後來接受中央命令前往福建、浙江進行海上的協防，陸續透過多場戰爭下平定外患，讓國家得以安定發展。」如果小櫻想要進一步了解戚繼光的生平，可以從哪個朝代的歷史進行調查？", "o": ["唐", "宋", "明", "清"], "a": 2, "e": "戚繼光是明代抗倭名將。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-88", "no": 88, "c": "d1", "src": "考卷 114上翰林社會2上B卷 卷6 題組 (二) 5（跨課）", "st": "考卷", "ctx": "小櫻在圖書館看到了歷史人物傳記的介紹如下：「戚繼光為 16 世紀明等著名的中國軍人軍事家。白幼年起就對於軍事的研究和學習非常熱衷，之後協助首都北京的防守並陸續平定北方民族的侵擾，受到中央的注目。然而，國家的外患不只陸上，即使中央頒布政策保護居民的安全，海上的外敵侵擾也頻繁發生。戚繼光後來接受中央命令前往福建、浙江進行海上的協防，陸續透過多場戰爭下平定外患，讓國家得以安定發展。」", "fig": "", "q": "文中提到北方的外敵，最可能為下列何者？", "o": ["契丹", "蒙古", "匈奴", "突厥"], "a": 1, "e": "明代北方的外患是蒙古。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-89", "no": 89, "c": "d7", "src": "考卷 114上翰林社會2上B卷 卷6 題組 (二) 6（跨課）", "st": "考卷", "ctx": "小櫻在圖書館看到了歷史人物傳記的介紹如下：「戚繼光為 16 世紀明等著名的中國軍人軍事家。白幼年起就對於軍事的研究和學習非常熱衷，之後協助首都北京的防守並陸續平定北方民族的侵擾，受到中央的注目。然而，國家的外患不只陸上，即使中央頒布政策保護居民的安全，海上的外敵侵擾也頻繁發生。戚繼光後來接受中央命令前往福建、浙江進行海上的協防，陸續透過多場戰爭下平定外患，讓國家得以安定發展。」", "fig": "", "q": "文中畫底線處所提到的政策，其應為下列何者？", "o": ["朝貢貿易", "海禁政策", "修築長城", "設市舶司"], "a": 1, "e": "為了防範海上外敵而禁止人民出海，是海禁政策。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-90", "no": 90, "c": "d11", "src": "考卷 114上翰林社會2上B卷 卷6 題組 (二) 7（跨課）", "st": "考卷", "ctx": "小櫻在圖書館看到了歷史人物傳記的介紹如下：「戚繼光為 16 世紀明等著名的中國軍人軍事家。白幼年起就對於軍事的研究和學習非常熱衷，之後協助首都北京的防守並陸續平定北方民族的侵擾，受到中央的注目。然而，國家的外患不只陸上，即使中央頒布政策保護居民的安全，海上的外敵侵擾也頻繁發生。戚繼光後來接受中央命令前往福建、浙江進行海上的協防，陸續透過多場戰爭下平定外患，讓國家得以安定發展。」", "fig": "", "q": "根據判斷，下列哪一個場景很可能會在戚繼光生活的時代發生？", "o": ["國家自占城引進新品種稻種種植成功", "中央與北方大國簽訂繳交歲幣的協定", "日本派留學生前來京城學習精華文化", "歐洲的傳教士前來並與中央官員交流"], "a": 3, "e": "戚繼光生活在 16 世紀明代後期，那時歐洲傳教士已經來華（例如利瑪竇）。占城稻是宋代；繳歲幣是宋遼；遣唐使是唐代。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-91", "no": 91, "c": "d1", "src": "考卷 114上翰林社會2上C卷 卷5 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "明朝在明成祖治理下，國勢達於鼎盛。下列哪一項並非明成祖的措施？", "o": ["修築長城", "北伐匈奴", "將首都遷到北京", "派鄭和下西洋"], "a": 1, "e": "明成祖北伐的是蒙古，不是匈奴。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-92", "no": 92, "c": "d1", "src": "考卷 114上翰林社會2上C卷 卷5 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "小茂在看一本介紹中國歷代皇帝的書，其中某位皇帝出身平民，從小父母早逝，為了生活，他當過乞丐、和尚等，後來從軍，驅逐蒙古人，結束異族的統治。依據上述內容判斷，此皇帝應為下列何者？", "o": ["明成祖", "秦始皇", "朱元璋", "李自成"], "a": 2, "e": "出身平民、當過和尚、驅逐蒙古的是朱元璋。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-93", "no": 93, "c": "d10", "src": "考卷 114上翰林社會2上C卷 卷5 第 3 題", "st": "考卷", "ctx": "", "fig": "圖(一)為大航海時代西班牙、葡萄牙跨洋航海路線圖", "q": "15 世紀末，歐洲人發現了通往亞洲的新航路，如圖(一)所示，當時西班牙、葡萄牙商人藉由圖中航路到中國貿易，主要是將中國的哪些物品帶到歐洲？", "o": ["玉米、番薯", "鐵皮、樟腦", "煙鹽、鴉片", "絲綢、瓷器"], "a": 3, "e": "西班牙、葡萄牙商人把中國的絲綢、瓷器帶到歐洲；玉米、番薯則是傳入中國的作物。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-global"], "chk": ""}, {"id": "h4-94", "no": 94, "c": "d8", "src": "考卷 114上翰林社會2上C卷 卷5 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "「這個時期，經濟發展方面，出現商品區域分工的特色，北方生產的棉花，經由水運賣到南方，南方織成的布，經由水運賣到北方。江南地區出現許多專業市鎮，如江蘇松江的織造、江西景德鎮的製瓷。」上述現象最早出現在下列哪個朝代？", "o": ["唐代", "宋代", "元代", "明代"], "a": 3, "e": "商品區域分工、出現景德鎮等專業市鎮，最早是在明代。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-95", "no": 95, "c": "d2", "src": "考卷 114上翰林社會2上C卷 卷5 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "「這個朝代除了面臨地方上的流寇作亂，又有蒙古、倭寇、女真族等外族的侵擾，在內憂外患的相逼迫下，最後走向滅亡。」依據上述內容判斷，此應是哪一個朝代？", "o": ["宋代", "元代", "明代", "清代"], "a": 2, "e": "流寇作亂，加上蒙古、倭寇、女真威脅，最後滅亡的是明代。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-96", "no": 96, "c": "d5", "src": "考卷 114上翰林社會2上C卷 卷5 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "在地圖尚未傳入中國前，中國認定其為全世界中心，以宗主國的角色進行國際往來關係，外國須藉由冊封才能以進貢方式與中國進行貿易，而周邊國家藉由冊封成為藩屬國，換取經濟利益或政治保護。依據上述內容判斷，此為何種體制？", "o": ["封建體制", "郡縣體制", "種族歧視", "天朝體制"], "a": 3, "e": "以中國為中心、外國接受冊封才能以進貢方式貿易，就是天朝體制。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-97", "no": 97, "c": "d11", "src": "考卷 114上翰林社會2上C卷 卷5 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "16 世紀以後，西方傳教士積極在東亞傳教，除了將西學輸入中國，他們也將中國文化傳到歐洲，促使歐洲形成一股「中國熱」的風潮。上述風潮中，從中國西傳的文物包含下列哪一項？", "o": ["火藥", "指南針", "儒家經典", "活字印刷術"], "a": 2, "e": "傳教士把儒家經典傳到歐洲，形成「中國熱」。火藥、指南針、印刷術是更早經其他途徑傳出的。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-98", "no": 98, "c": "d9", "src": "考卷 114上翰林社會2上C卷 卷5 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "番薯、玉米等作物的引入，改變了中國糧食作物的來源，這些作物是在下列何時傳入中國？", "o": ["唐代", "宋代", "元代", "明代"], "a": 3, "e": "番薯、玉米是在明代從美洲傳入中國的。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-global"], "chk": ""}, {"id": "h4-99", "no": 99, "c": "d10", "src": "考卷 114上翰林社會2上C卷 卷5 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "從事絲綢與瓷器貿易的明代商人，在日常生活當中，不可能發生下列哪一件事？", "o": ["他可以加入自己家鄉的商幫", "遇到西班牙人向自己買貨物", "和外國人交易時以紙幣為主", "外出做生意時可住在會館內"], "a": 2, "e": "明代對外貿易使用白銀，不是以紙幣為主。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-100", "no": 100, "c": "d3", "src": "考卷 114上翰林社會2上C卷 卷5 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "清雍正年間，有一文人寫了「明月有情還顧我，清風無意不留人」；乾隆年間，另一文人寫了「一把心腸論濁清」的詩句，朝廷認為兩人詆毀大清，均被處死。這是因為清帝國實施的哪一政策？", "o": ["文字獄", "薙髮留辮", "種族政策", "朝貢貿易"], "a": 0, "e": "因詩句被認為詆毀朝廷而被處死，是文字獄。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-101", "no": 101, "c": "d13", "src": "考卷 114上翰林社會2上C卷 卷5 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "17 世紀日本實施鎖國政策後，只允許某個歐洲國家在長崎進行有限的貿易活動，長崎當時成為西方文化流入的窗口。上述的歐洲國家應為下列何者？", "o": ["英國", "荷蘭", "法國", "西班牙"], "a": 1, "e": "日本鎖國時只准荷蘭在長崎進行有限的貿易。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-102", "no": 102, "c": "d12", "src": "考卷 114上翰林社會2上C卷 卷5 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "18 世紀初，中國與西方世界的交流突然中斷，最主要的原因為下列何者？", "o": ["雍正皇帝下令禁教", "康熙皇帝實施海禁", "流寇勢力逐漸壯大", "倭寇嚴重侵擾邊疆"], "a": 0, "e": "18 世紀初雍正下令禁教，中國與西方的交流因此中斷。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-103", "no": 103, "c": "d10", "src": "考卷 114上翰林社會2上C卷 卷5 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "明初貨幣原以紙幣為主，後來形成以白銀及銅錢並用的制度，造成貨幣制度改變的主要原因為何？", "o": ["專業市鎮的興起", "海禁政策的實施", "派遣鄭和下西洋", "對外貿易的發達"], "a": 3, "e": "對外貿易發達、白銀大量流入，才形成白銀與銅錢並用的制度。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-global"], "chk": ""}, {"id": "h4-104", "no": 104, "c": "d7", "src": "考卷 114上翰林社會2上C卷 卷5 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "「這群人為禍中國東南沿海，使明代商旅經商不便，除了要躲避政府的海禁查緝，還要提心吊膽來自海上這群人的威脅。」上述「這群人」應是指下列何者？", "o": ["流寇", "宦官", "倭寇", "女真"], "a": 2, "e": "為禍東南沿海、威脅商旅的是倭寇。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-105", "no": 105, "c": "d3", "src": "考卷 114上翰林社會2上C卷 卷5 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "明朝末年，流寇攻陷北京，導致明朝滅亡。而後清兵在駐守山海關的將領協助下入關，消滅流寇，建立政權。依據上述內容判斷，此將領應為下列何者？", "o": ["吳三桂", "鄭成功", "鄭芝龍", "顏思齊"], "a": 0, "e": "駐守山海關、引清兵入關的是吳三桂。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-106", "no": 106, "c": "d6", "src": "考卷 114上翰林社會2上C卷 卷5 第 16 題", "st": "考卷", "ctx": "", "fig": "圖(二)為明代《瑞應麒麟圖》長頸鹿古畫書影", "q": "圖(二)為西元 1424 年，位於印度洋的榜葛剌國（今孟加拉）進獻中國的瑞獸「麒麟」。榜葛剌國進獻物品給中國，與下列哪一背景因素有關？", "o": ["蒙古西征", "張騫通西域", "鄭和出使西洋", "耶穌會傳教士東來"], "a": 2, "e": "1424 年榜葛剌國進獻麒麟（長頸鹿），和鄭和出使西洋、擴大朝貢有關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-zhenghe"], "chk": ""}, {"id": "h4-107", "no": 107, "c": "d3", "src": "考卷 114上翰林社會2上C卷 卷5 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "清帝國統治中國後，所採取的統治策略，不包括下列何者？", "o": ["大興文字獄", "強迫漢人薙髮留辮", "禮遇文士、舉行科舉", "實施區分四等人的種族政策"], "a": 3, "e": "清朝採高壓（文字獄、薙髮）與懷柔（科舉）並行；區分四等人的種族政策是元朝的做法。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "選項 (D)"}, {"id": "h4-108", "no": 108, "c": "d2", "src": "考卷 114上翰林社會2上C卷 卷5 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "「我本來只是個農民，後來因為發生嚴重飢荒，我只好加入『流寇』的陣營，最後更成為流寇的領袖，並於西元 1644 年攻陷北京，造成明帝國滅亡。」上述應是指下列何人？", "o": ["李自成", "吳三桂", "朱元璋", "趙匡胤"], "a": 0, "e": "農民出身、加入流寇並在 1644 年攻陷北京的是李自成。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-109", "no": 109, "c": "d11", "src": "考卷 114上翰林社會2上C卷 卷5 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "「他在 16 世紀末抵達，進獻了繪有經緯度的《坤輿萬國全圖》，將西方的地理知識傳入中國，為使得教能順利進行，特別容許中國教徒可以祭祖、祭孔。」如果想要了解上述此人的事蹟，可以參考下列哪一本書籍？", "o": ["《利瑪竇傳教日誌》", "《清世宗雍正實錄》", "《鄭和下西洋日誌》", "《荷蘭東印度公司日誌》"], "a": 0, "e": "16 世紀末來華、進獻《坤輿萬國全圖》、容許教徒祭祖祭孔的是利瑪竇。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-110", "no": 110, "c": "d4", "src": "考卷 114上翰林社會2上C卷 卷5 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "清兵入關後，康雍乾三代帝王勵精圖治，事必躬親，提高經濟實力，加強中央集權統治，而締造出輝煌的百年盛世。有關此時期的文治武功，下列敘述何項正確？", "o": ["派遣龐大艦隊出使西洋", "廣設驛站發展國際貿易", "將臺灣、新疆納入版圖", "發動西征建立四大汗國"], "a": 2, "e": "康雍乾時期把臺灣、新疆納入版圖。下西洋是明成祖；廣設驛站、發動西征是元代（蒙古）。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-qing"], "chk": ""}, {"id": "h4-111", "no": 111, "c": "d1", "src": "考卷 114上翰林社會2上C卷 卷5 進階思考題 1", "st": "考卷", "ctx": "", "fig": "", "q": "右表是「明朝歲出與軍費支出統計表」，由內容可知，耗垮明朝財政的是「長年對外用兵」。上述明朝對外用兵的對象，不包括下列何者？", "o": ["契丹", "女真", "倭寇", "蒙古"], "a": 0, "e": "明朝用兵的對象是女真、倭寇、蒙古；契丹是宋代的外患。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-112", "no": 112, "c": "d9", "src": "考卷 114上翰林社會2上C卷 卷5 進階思考題 2", "st": "考卷", "ctx": "", "fig": "", "q": "「某一市場中，人群川流不息，販賣各種商品，例如棉布、絲織品、香料、金銀飾品、玉米、番薯等。市場中有多家販售來自景德鎮市鎮運來的瓷器。」這個市場最可能發生在下列哪個時空背景？", "o": ["西元 8 世紀的長安", "西元 11 世紀的汴京", "西元 13 世紀的大都", "西元 16 世紀的北京"], "a": 3, "e": "有玉米、番薯和景德鎮瓷器，是 16 世紀明代的北京。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-113", "no": 113, "c": "d11", "src": "考卷 114上翰林社會2上C卷 卷5 進階思考題 3", "st": "考卷", "ctx": "", "fig": "圖(三)為利瑪竇與徐光啟畫像示意圖", "q": "圖(三)為明末清初天主教傳教士在中國傳教的示意圖，他曾和漢人徐光啟合譯一本書籍，這本書是古希臘數學家歐幾里得的著作，奠定了歐洲數學的基礎，此書名應為下列何者？", "o": ["微積分", "三角函數", "幾何原本", "百科全書"], "a": 2, "e": "利瑪竇和徐光啟合譯的是歐幾里得的《幾何原本》。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-114", "no": 114, "c": "d6", "src": "考卷 114上翰林社會2上C卷 卷5 進階思考題 4", "st": "考卷", "ctx": "", "fig": "", "q": "下列有關「鄭和出使西洋」的敘述，何者不正確？", "o": ["派遣鄭和出使的是明成祖", "「西洋」指今日的大西洋", "沿海居民大量移居東南亞", "擴大明帝國朝貢貿易規模"], "a": 1, "e": "「西洋」指今日的東南亞、印度洋，不是大西洋。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-zhenghe"], "chk": ""}, {"id": "h4-115", "no": 115, "c": "d3", "src": "考卷 114上翰林社會2上C卷 卷5 進階思考題 5", "st": "考卷", "ctx": "", "fig": "", "q": "下列是三個不同時期朝代的官員描述，根據其描述的史實，按照朝代的先後順序排列為何？\n(甲)中央政府及地方上的行政首長，大多由蒙古貴族擔任。\n(乙)漢人文官們被迫薙髮留辮，有人因寫的詩文被皇帝指為詆毀。\n(丙)朝廷聽聞契丹被南侵中國，有官員主張皇帝親征以振拔士氣。", "o": ["甲乙丙", "乙甲丙", "丙甲乙", "丙乙甲"], "a": 2, "e": "丙是北宋澶淵之盟、甲是元代蒙古貴族掌權、乙是清代薙髮與文字獄，順序是丙甲乙。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-116", "no": 116, "c": "d5", "src": "考卷 114上翰林社會2上C卷 卷5 進階思考題 6", "st": "考卷", "ctx": "", "fig": "", "q": "關於明清時期的經濟發展，下列敘述何者正確？", "o": ["玉米、番薯、馬鈴薯等作物從占城引進中國", "開始出現不受營業時間和地點限制的夜市", "明初為了打擊鄭氏政權，曾實施海禁政策", "明代在海禁期間對外貿易採「朝貢貿易」"], "a": 3, "e": "明代海禁期間，對外貿易採朝貢貿易。美洲作物不是從占城引進；夜市始於宋代；打擊鄭氏的海禁是清初。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-117", "no": 117, "c": "d11", "src": "考卷 114上翰林社會2上C卷 卷5 進階思考題 7", "st": "考卷", "ctx": "", "fig": "", "q": "某一演講中提到「張騫與絲路、利瑪竇與西學」等人物的事蹟，這次演講的主題最與下列何者有關？", "o": ["東西文化交流", "白銀傳入中國", "朝貢貿易體系", "新航路的發現"], "a": 0, "e": "張騫通西域、利瑪竇傳入西學，都是東西文化交流。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-118", "no": 118, "c": "d5", "src": "考卷 114上翰林社會2上C卷 卷5 題組 (一) 1", "st": "考卷", "ctx": "", "fig": "", "q": "16 世紀世界變動快速，中國進入明代後，朝貢貿易興盛，中外交流密切。此時西方因為航海技術進步，海外新世界成為各國爭雄的目標。他們爭先恐後來到富庶的東方貿易、傳道和開發新據點。朝貢貿易是指外國須接受中國的冊封，才能以進貢的名義進行貿易。明清時期對外貿易管制如此狹隘的原因，與當時實施哪一項政策有關？", "o": ["科舉制度", "海禁政策", "和親政策", "禁教政策"], "a": 1, "e": "明清實施海禁，民間不能出海，對外只剩官方的朝貢貿易。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-119", "no": 119, "c": "d7", "src": "考卷 114上翰林社會2上C卷 卷5 題組 (一) 2", "st": "考卷", "ctx": "16 世紀世界變動快速，中國進入明代後，朝貢貿易興盛，中外交流密切。此時西方因為航海技術進步，海外新世界成為各國爭雄的目標。他們爭先恐後來到富庶的東方貿易、傳道和開發新據點。朝貢貿易是指外國須接受中國的冊封，才能以進貢的名義進行貿易。", "fig": "", "q": "承上題，清代初期實施此一政策的目的應為下列何者？", "o": ["對付倭寇", "全面禁教", "打擊鄭氏", "消滅流寇"], "a": 2, "e": "清初實施海禁是為了打擊臺灣鄭氏。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-120", "no": 120, "c": "d13", "src": "考卷 114上翰林社會2上C卷 卷5 題組 (二) 3", "st": "考卷", "ctx": "", "fig": "圖(四)為日本浮世繪《浮世美人奇花》手持望遠鏡女子畫作", "q": "17 世紀日本社會隨著經濟繁榮，人民財富累積與城市享樂風氣盛行，出現了描繪市民階層生活與藝妓等人物書、風景畫，因為反映市民生活景象，又被稱為「浮世繪」。圖(四)為《浮世美人奇花》中使用望遠鏡的女孩，其手中的望遠鏡是從歐洲傳入日本，當時日本只開放長崎一個港口對外貿易，外國人來到日本只能待在長崎附近的「出島」，與日本人民隔離，但外國人帶來的望遠鏡與西方學說仍融入於日本人的生活中，並帶來生活上的改變。圖(四)中出現的背景，與當時日本實施哪一政策有關？", "o": ["海禁", "鎖國", "明治維新", "大化革新"], "a": 1, "e": "只開放長崎、外國人被隔離在出島，是日本的鎖國政策。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-121", "no": 121, "c": "d13", "src": "考卷 114上翰林社會2上C卷 卷5 題組 (二) 4", "st": "考卷", "ctx": "17 世紀日本社會隨著經濟繁榮，人民財富累積與城市享樂風氣盛行，出現了描繪市民階層生活與藝妓等人物書、風景畫，因為反映市民生活景象，又被稱為「浮世繪」。圖(四)為《浮世美人奇花》中使用望遠鏡的女孩，其手中的望遠鏡是從歐洲傳入日本，當時日本只開放長崎一個港口對外貿易，外國人來到日本只能待在長崎附近的「出島」，與日本人民隔離，但外國人帶來的望遠鏡與西方學說仍融入於日本人的生活中，並帶來生活上的改變。", "fig": "", "q": "承上題，圖中望遠鏡與相關學說，最可能是哪一國家的人所傳入？", "o": ["法國", "英國", "荷蘭", "西班牙"], "a": 2, "e": "鎖國時待在長崎出島、帶來望遠鏡與西方學說的是荷蘭人。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-122", "no": 122, "c": "d2", "src": "考卷 114上翰林社會2上C卷 卷6 第 12 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "老師在介紹某朝代的內憂外患時提到下列的重點。由內容判斷，老師在介紹下列哪一朝代？\n邊防外患崛起於東北，與其長期對峙。\n國內面臨嚴重飢荒，大批災民與飢兵形成流寇。\n日本和中國海盜在東南海走私和貿易。", "o": ["宋代", "元代", "明代", "清代"], "a": 2, "e": "東北外患（女真）、饑荒引發流寇、東南倭寇，都是明代的內憂外患。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-123", "no": 123, "c": "d9", "src": "考卷 114上翰林社會2上C卷 卷6 第 14 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "新航路開闢之後，玉米、番薯、馬鈴薯等作物導入中國，這些耐旱多產的作物，解決了當時中國的何種問題？", "o": ["人口快速增加", "作物種類過少", "飲食習慣改變", "糧食價格低廉"], "a": 0, "e": "美洲作物耐旱高產，解決了人口快速增加帶來的糧食問題。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-124", "no": 124, "c": "d2", "src": "考卷 114上翰林社會2上C卷 卷6 第 15 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "明末饑荒造成災民與飢兵結合形成流寇，其中某將領的勢力最大，不僅有「闖王」之稱，為患期間使吳三桂失去愛妾陳圓圓，使得吳三桂開啟山海關，引清兵入關消滅流寇。根據上述內容判斷，「某將領」應是下列何者？", "o": ["鄭芝龍", "李自成", "顏思齊", "朱元璋"], "a": 1, "e": "有「闖王」之稱、流寇勢力最大的是李自成。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-125", "no": 125, "c": "d8", "src": "考卷 114上翰林社會2上C卷 卷6 進階思考題 1（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "中國隨著市場擴大與分工逐漸細密，工商業出現下列的發展，此發展興起於何時？「瓷器與絲織業市鎮：盛澤鎮、震澤鎮、雙林鎮；棉花與棉格紡織業市鎮：三林塘鎮、朱家角鎮、江灣鎮」", "o": ["秦漢時期", "隋唐時期", "宋元時期", "明清時期"], "a": 3, "e": "絲織、棉紡等專業市鎮是明清時期興起的。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-126", "no": 126, "c": "d12", "src": "考卷 114上翰林社會2上C卷 卷6 進階思考題 5（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "大導演周星星計畫拍攝一部以明代中葉為背景的古裝劇，導演特別要求編劇人員加入較能凸顯當代社會生活的劇情。下列哪一段劇情不適合出現在電影中？", "o": ["皇帝下令禁教，中西交流中斷", "市場小販叫賣著剛煮好的玉米", "民眾在飯館用餐使用白銀付帳", "員外家使用青花瓷器裝盛花束"], "a": 0, "e": "禁教是清朝雍正時的事，不會出現在明代中葉。玉米、白銀、青花瓷明代都有。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-127", "no": 127, "c": "d1", "src": "考卷 114上翰林社會2上C卷 卷6 進階思考題 6（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "中國此朝代中期以後，曾經抵達非洲東岸的官方遠洋航行，因無法負荷龐大的支出而終止；東南沿海地區遭海盜劫掠，且日益頻繁。幾任皇帝雖整修長城，依然抵擋不住北方蒙古族的侵擾。由上述對外關係的介紹可判斷，最可能為下列哪個朝代？", "o": ["南宋", "元代", "明代", "清代"], "a": 2, "e": "遠洋航行到非洲東岸（鄭和）、東南沿海海盜（倭寇）、修長城防蒙古，都是明代的對外情勢。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-128", "no": 128, "c": "d3", "src": "考卷 114上翰林社會2上C卷 卷6 題組 (一) 2（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "西元 17 世紀，清兵之所以能順利進入山海關，與漢人將領受節授降有關。這位將領應為下列何人？", "o": ["岳飛", "徐光啟", "趙匡胤", "吳三桂"], "a": 3, "e": "清兵能順利進入山海關，是因為吳三桂降清。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-129", "no": 129, "c": "d8", "src": "考卷 114上翰林社會2上C卷 卷6 題組 (二) 3（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "15～17 世紀時期歐洲為了與亞洲貿易，尋找海上新航路，最終終於來到了中國，以白銀購買中國與鄰近地區的商品轉賣到歐洲，賺取大量利潤。圖(二)中對甲商品的採購，與中國當時哪一經濟發展密切相關？", "o": ["指南針用於航海", "瓷器專業市鎮興起", "引進早熟稻栽種", "南洋各國前來朝貢"], "a": 1, "e": "甲在絲綢旁邊，是瓷器。歐洲大量採購中國瓷器，和景德鎮等瓷器專業市鎮興起有關。", "rep": false, "img": "h4-q129", "imgnote": "", "fh": "", "maps": ["h4-global"], "chk": ""}, {"id": "h4-130", "no": 130, "c": "d10", "src": "考卷 114上翰林社會2上C卷 卷6 題組 (二) 4（跨課）", "st": "考卷", "ctx": "15～17 世紀時期歐洲為了與亞洲貿易，尋找海上新航路，最終終於來到了中國，以白銀購買中國與鄰近地區的商品轉賣到歐洲，賺取大量利潤。", "fig": "", "q": "承上題，白銀傳入中國後，形成白銀與銅錢並用的制度，上述貨幣主要是從哪一個地區引入？", "o": ["亞洲", "歐洲", "美洲", "非洲"], "a": 2, "e": "流入中國的白銀主要來自美洲（西班牙在美洲開採）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-global"], "chk": ""}, {"id": "h4-131", "no": 131, "c": "d3", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "長城是遊牧民族進入中國的一道障礙，然而清朝能夠直接進入山海關，輕鬆入主中國，其原因與下列何人有關？", "o": ["李自成", "吳三桂", "朱元璋", "鄭和"], "a": 1, "e": "吳三桂打開山海關，清兵才能輕鬆入關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-132", "no": 132, "c": "d1", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "電影《長城》氣勢磅礴，描述長城作為防守怪獸發強大軍的入侵，而在真實歷史上，長城在不同時期均是擔任防守不同北方外族的軍事建築。明代時期長城所防守的外族為下列何者？", "o": ["突厥、犬戎", "匈奴、蒙古", "契丹、女真", "蒙古、女真"], "a": 3, "e": "明代的長城主要防守蒙古與女真。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-133", "no": 133, "c": "d11", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "純真到歐洲旅遊，看到許多博物館中收藏不少中國古代的瓷器如右圖，這些瓷器有些是青花瓷，有些則是其他花紋的瓷器……。這些瓷器的西傳與下列哪一件事有關？", "o": ["馬可波羅東來", "長老會傳教士東來", "伊斯蘭教傳播中國", "耶穌會傳教士東來"], "a": 3, "e": "傳教士把中國瓷器、園林等文化介紹回歐洲，帶動瓷器西傳。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-134", "no": 134, "c": "d9", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "大航海時代，西班牙經由美洲傳入的新作物，解決了中國當時糧食不足的問題，這些作物不包括下列何者？", "o": ["玉米", "甘蔗", "番薯", "馬鈴薯"], "a": 1, "e": "甘蔗不是美洲作物；玉米、番薯、馬鈴薯才是。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-135", "no": 135, "c": "d11", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "明末來到來華的傳教士，主要屬於歐洲哪一個宗教派別？", "o": ["耶穌會", "伊斯蘭教", "長老教會", "基督教"], "a": 0, "e": "明末來華的傳教士主要是天主教耶穌會。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-136", "no": 136, "c": "d3", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "許多被清朝統治的明朝知識分子，雖然難忘亡國之痛，但是隨即針對朝廷提供的某項「政策」感到嚮往，甚至投入清朝統治體系之中。依中國歷史來判斷，該項政策最可能是下列何者？", "o": ["薙髮留辮", "自由結社", "廣開科舉", "文字獄"], "a": 2, "e": "清朝照常舉行科舉，吸引明朝的知識分子投入。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-137", "no": 137, "c": "d1", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "鄭和以宦官的身分受到重用，率領代表中國權威的大型艦隊下西洋，是明朝某一位皇帝對他的器重。下列歷來事件中，何者亦是這一位明朝皇帝的作為？", "o": ["領導災民及餓兵攻入首都", "實施禁教，造成東西文化交流中斷", "為防範蒙古勢力遷都北京並修築長城", "投降於外族勢力，引其入關取代前朝統治"], "a": 2, "e": "派鄭和下西洋的是明成祖，他也為了防範蒙古遷都北京、修築長城。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-138", "no": 138, "c": "d9", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "2018 年中國人口統計處的一份報告指出：「中國近代歷史上，從清朝後，人口不同於千餘年的停滯狀態，而是呈現爆炸性的增加，直至今日。」根據判斷，「清初」是中國人口爆炸性成長關鍵時間點的原因，最可能為下列何者？", "o": ["因為傳教士傳入西方醫學", "因為《幾何原本》的翻譯", "因為社會內部沒有任何戰亂", "因為自外國傳入美洲的糧食作物"], "a": 3, "e": "清初人口暴增，主要是因為美洲高產作物傳入。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-139", "no": 139, "c": "d2", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列為明朝《流民圖》，描繪一位骨瘦如柴，到處乞食的逃荒難民，顯示明朝飽受內憂外患之苦。下列何者不是明朝的內憂外患之一？", "o": ["倭寇侵擾", "流寇之亂", "鄭氏在臺勢力", "滿洲外族勢力"], "a": 2, "e": "明朝的內憂外患有倭寇、流寇、滿洲；臺灣鄭氏是清初的對手，不是明朝的。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-ming"], "chk": ""}, {"id": "h4-140", "no": 140, "c": "d11", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "明末傳入中國的天主教，具有什麼不一樣的特色，故獲得中國人的認同，而得以在中國發展？", "o": ["傳入儒學", "可以念佛", "可以祭祖祀孔", "不需薙髮留辮"], "a": 2, "e": "利瑪竇容許中國教徒祭祖、祀孔，所以天主教較能被中國人接受。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-141", "no": 141, "c": "d12", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "部分學者認為，早期中國將四大發明傳入西方，18、19 世紀，歐洲因幾次的改革而掌握海權優勢，中國已相對落後。但中國並非絕無引進西方科學，造成中國與西方的文化交流中斷的原因為何？", "o": ["蒙古西征", "明朝海禁政策", "清朝海禁政策", "清帝國實施禁教"], "a": 3, "e": "清朝（雍正）實施禁教，中西文化交流因此中斷。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-142", "no": 142, "c": "d6", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據右列的報導，菲律賓地區會出現華裔人士的原因，與下列何時對南洋的經營，使得華人首次大規模移居菲律賓的關係最為密切？", "o": ["宋朝", "元朝", "明朝", "清朝"], "a": 2, "e": "明朝鄭和下西洋經營南洋，華人開始大規模移居菲律賓等東南亞地區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-zhenghe"], "chk": ""}, {"id": "h4-143", "no": 143, "c": "d12", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "佳玲在《中國歷史》一書中看到專章中針對其中一位皇帝的介紹如下圖，據判斷，其應該是哪一朝代的哪位帝王？「他即位之後，下令禁教，導致中西交流中斷。此後，西方的科技日益進步，而中國長期閉關，不了解世界情勢的演變發展。百年後，難與西方列強對抗，落得躺平，就是一連串悲劇的開端。」", "o": ["宋朝，趙匡胤", "元朝，忽必烈", "明朝，朱元璋", "清朝，雍正"], "a": 3, "e": "下令禁教、導致中西交流中斷的是清朝雍正。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-144", "no": 144, "c": "d6", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "上圖的航海路線說明了下列哪一歷史事件？", "o": ["張騫通西域", "鄭和下西洋", "蒙古西征", "南洋勢力擴張"], "a": 1, "e": "航線從中國經東南亞、印度洋到非洲東岸，是鄭和下西洋。", "rep": false, "img": "h4-q144", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-145", "no": 145, "c": "d12", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "15、16 世紀末，歐洲人首次發現到東方的新航路，此後中西交流絡繹不絕。但清朝時實施閉關自守政策，中西交流自此陷入停頓狀態，原因為下列何者？", "o": ["為防鄭氏，實施海禁", "列強侵略中國，清廷乃驅離外國商人", "教宗禁止中國信徒祭祖，清帝限制傳教", "傳教士捲入宮廷政爭，清帝乃明令禁教"], "a": 3, "e": "雍正因為傳教士捲入宮廷政爭而下令禁教。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-146", "no": 146, "c": "d12", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "建銘正在觀賞中國宮廷古裝劇，劇中的皇帝採取禁止西方宗教來華傳教的政策。關於這位皇帝的敘述，下列何者正確？", "o": ["派遣鄭和下西洋", "是明朝的帝王", "其父親應為康熙皇帝", "定都應天，結束前朝統治"], "a": 2, "e": "下令禁教的是雍正，他的父親是康熙。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-147", "no": 147, "c": "d4", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "在中國歷史上，長城以北的草原民族與中原農業民族呈現長期的對峙，直到下列哪一個朝代的出現才結束？", "o": ["宋朝", "元朝", "明朝", "清朝"], "a": 3, "e": "清朝把蒙古納入版圖，草原民族與農業民族的長期對峙才結束。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-qing"], "chk": ""}, {"id": "h4-148", "no": 148, "c": "d11", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "國立故宮博物院曾經舉行「康熙大帝與太陽王路易十四特展」，這兩位在 17 世紀末，東方與西方最偉大的君主，帶來了中西文化的碰撞。中國與法國這二位分居兩地的君主，當時是透過哪種媒介，產生了間接接觸？", "o": ["基督教長老教會傳教士", "天主教耶穌會傳教士", "義大利商人馬可波羅", "從海路上絲路的商人"], "a": 1, "e": "康熙與路易十四是透過天主教耶穌會傳教士間接接觸的。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-149", "no": 149, "c": "d5", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國宋、元以來發達的海上貿易，後來轉變為官方掌握的「朝貢貿易」，其主要原因為下列何者？", "o": ["明太祖實施「海禁政策」", "新航路發現後，歐人東來", "清康熙實施「海禁政策」", "清雍正禁教，驅逐天主教傳教士"], "a": 0, "e": "明太祖實施海禁，民間海上貿易轉變為官方掌控的朝貢貿易。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-150", "no": 150, "c": "d9", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "「從 17 世紀中葉一直到 20 世紀初，中國人口從 1 億 5 千萬增加到 4 億以上。」上述中國人口數之所以增加的主要原因為何？", "o": ["中國領土大規模的擴展", "美洲新作物的導入與推廣", "中國人民生育能力大幅提高", "沒有發生導致人口大量減少的戰亂"], "a": 1, "e": "17 世紀中葉以後人口大增，主要是因為美洲新作物的引進與推廣。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-151", "no": 151, "c": "d10", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "上歷史課時，同學們討論有關「明清時期」工商業的發展。下列哪位同學的說法錯誤？", "o": ["子瑜：手工業細密，專業市鎮興起", "多賢：貨幣主要以紙幣為主", "志效：江西景德鎮以生產瓷器聞名", "定延：明清曾實施海禁，對國際貿易造成影響"], "a": 1, "e": "明清的貨幣是白銀與銅錢並用，不是以紙幣為主。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-152", "no": 152, "c": "d3", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "崛起於東北的女真族在明朝末年改名滿洲，再度成為威脅中原政權的勢力，後入關統治中國之初，為鞏固政權極力而實施「高壓與懷柔」並行的政策。下列何者屬「懷柔」政策？", "o": ["文字獄", "海禁", "舉行科舉", "薙髮留辮"], "a": 2, "e": "舉行科舉是懷柔政策；文字獄、薙髮留辮是高壓。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-153", "no": 153, "c": "d11", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "歐洲傳教士將西方知識與技術傳入中國，下列何者不包括在內？", "o": ["幾何數學", "絲綢瓷器", "天文曆法", "火炮技術"], "a": 1, "e": "絲綢、瓷器是中國傳到西方的商品，不是傳教士傳入的西方知識。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-154", "no": 154, "c": "d11", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "英國萬本公園的湖畔有亭臺樓閣、迴廊建築，再加上垂柳湖畔，頗具中國園林的特色。上述這項文化的影響與下列何者的關係最密切？", "o": ["鄭和下西洋", "蒙古三次西征", "張騫出使西域", "天主教傳教士的推廣"], "a": 3, "e": "中國園林風格傳到歐洲，和天主教傳教士的介紹有關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-155", "no": 155, "c": "d10", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 第 25 題", "st": "考卷", "ctx": "", "fig": "", "q": "明朝中葉以後，西班牙人與中國進行絲貨貿易，使得西班牙由中南美洲開採的白銀大量流入中國，因而改變中國的貨幣制度。上述所言的中南美洲「白銀」，其主要經由下列何地輸入中國？", "o": ["廣州", "臺灣", "北京", "菲律賓"], "a": 3, "e": "西班牙在菲律賓馬尼拉轉運美洲白銀到中國。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["h4-global"], "chk": ""}, {"id": "h4-156", "no": 156, "c": "d10", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 題組 (一) 26", "st": "考卷", "ctx": "", "fig": "", "q": "「一條鞭法」是明朝嘉靖時期確立的賦稅及徭役制度，發明者為桂萼，由張居正於 1581 年推行到全國。根據上述，明朝官方規定用白銀繳稅最有可能是與下列何者有關？", "o": ["白銀大量流入民間", "銅錢鑄造數量不足", "廢除銅錢作為貨幣", "紙鈔發行浮濫貶值"], "a": 0, "e": "白銀大量流入民間，明朝才能規定用白銀繳稅（一條鞭法）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-157", "no": 157, "c": "d10", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 題組 (一) 27", "st": "考卷", "ctx": "「一條鞭法」是明朝嘉靖時期確立的賦稅及徭役制度，發明者為桂萼，由張居正於 1581 年推行到全國。", "fig": "", "q": "承上題，根據上述，當時明朝可能主要是透過何種方式來獲得白銀？", "o": ["販售茶葉", "販售瓷器", "販售香料", "販售玉米"], "a": 1, "e": "明朝主要靠販售瓷器、絲綢給歐洲商人來換取白銀。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-global"], "chk": ""}, {"id": "h4-158", "no": 158, "c": "d7", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 題組 (二) 28", "st": "考卷", "ctx": "", "fig": "", "q": "某位官員綜合國家所做的政策提到一段說法如下：「本朝與前朝皆施禁令，所防皆為海寇，諭令片板不得入海。本朝為求禁令得以落實，遍閱江浙四省沿海眾民入陸，以絕後患。」上述的官員應該是隸屬哪個時代？", "o": ["明初", "明末", "清初", "清末"], "a": 2, "e": "「本朝與前朝皆施禁令」，還遷移沿海居民入內陸（遷界），是清初。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-159", "no": 159, "c": "d7", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 題組 (二) 29", "st": "考卷", "ctx": "某位官員綜合國家所做的政策提到一段說法如下：「本朝與前朝皆施禁令，所防皆為海寇，諭令片板不得入海。本朝為求禁令得以落實，遍閱江浙四省沿海眾民入陸，以絕後患。」", "fig": "", "q": "上文官員提到「本朝」比前朝更加強禁令的限制，主要是針對哪一勢力？", "o": ["倭寇", "鄭氏", "歐洲", "南洋"], "a": 1, "e": "清初加強海禁、實施遷界，主要是為了打擊臺灣鄭氏。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-160", "no": 160, "c": "d7", "src": "考卷 114上金安翰版社會2上A卷 第5次練習 題組 (二) 30", "st": "考卷", "ctx": "某位官員綜合國家所做的政策提到一段說法如下：「本朝與前朝皆施禁令，所防皆為海寇，諭令片板不得入海。本朝為求禁令得以落實，遍閱江浙四省沿海眾民入陸，以絕後患。」", "fig": "", "q": "居住在中國何地的居民受到此一國家政策的影響最大？", "o": ["東南沿海居民", "首都北京民眾", "陝甘地區居民", "四川「天府之國」居民"], "a": 0, "e": "海禁影響最大的是靠海維生的東南沿海居民。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-161", "no": 161, "c": "d2", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 2 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "雍正皇帝在《大義覺迷錄》中曾為自己辯護表示：「清朝與明朝的關係並非敵國，而是友邦。清朝是明朝的鄰居，因憾於明朝滅亡，故引兵入關為明朝復仇。」根據上述內容，雍正認為明朝應該是亡於何人之手？", "o": ["鄭成功", "李自成", "吳三桂", "鄭和"], "a": 1, "e": "雍正說清朝是替明朝報仇，表示他認為明朝亡於李自成。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-162", "no": 162, "c": "d11", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 10 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "「15 世紀時，歐洲傳教士隨商人來華傳教，將西方的數學、地理學、天文、曆法、火器、科學等引進中國，也將中國的瓷器、繪畫、園林建築等傳回西方社會，促進中西文化交流。」由西方傳入的典籍中，最著名的是下列哪一本書？", "o": ["孟子", "中庸", "幾何原本", "論語"], "a": 2, "e": "傳教士引進的西方典籍中，最著名的是《幾何原本》。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-163", "no": 163, "c": "d2", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 13 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "明末，崇禎皇帝自縊身殉國前，曾感慨地說過一段話（如圖），崇禎口中所指的「逆賊」為下列何者？「朕自登基十七年，逆賊直逼京師，致雪君社稷，朕死無面目見祖宗於地下……」", "o": ["鄭和", "朱熹", "吳三桂", "李自成"], "a": 3, "e": "崇禎口中直逼京師的「逆賊」是李自成。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-164", "no": 164, "c": "d4", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 15 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "志銘是一位清康熙時期來到中國經商的外國人，他會經歷哪一事件？", "o": ["發現蒙古人、色目人獲得政治和經濟上的特權", "聽到攻打鄭氏政權成功的消息", "皇帝派遣使節鄭和下西洋", "流寇四起，並攻陷京城"], "a": 1, "e": "康熙時派施琅攻下臺灣鄭氏政權（1683 年），外國商人可能聽到這個消息。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-qing"], "chk": ""}, {"id": "h4-165", "no": 165, "c": "d12", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 16 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "《甄嬛傳》演出雍正王朝，引發兩岸三地陷入「甄嬛效應」，有些學生因此求史、戲劇野史分不清。例如劇中雍正周旋在數十位妃子，彷彿是好色之徒，但是正史記載，雍正是一個工作狂，對女色並不熱衷。以下哪一件事情是符合歷史上真實雍正的作為？", "o": ["驅逐蒙古人，並在應天建都，結束前朝統治", "以傳教士介入宮廷政爭為由，實施禁教", "算無遺策，出外旅遊引發避暑之盟", "將臺灣納入版圖，開創大清盛世"], "a": 1, "e": "雍正以傳教士介入宮廷政爭為由實施禁教。攻臺是康熙；定都應天是朱元璋。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-166", "no": 166, "c": "d6", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 19 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "資料一：「觀夫海洋，洪濤接天，巨浪如山，視諸夷域，迥隔於煙霞縹緲之間。而我之雲帆高張，晝夜星馳，涉彼狂瀾，若履通衢者……」資料二：「皇明混一海宇，超三代而軼漢唐……自永樂三年，奉使西洋，迄今七次，所歷番國，由占城國……木骨都束國，大小凡三十餘國，涉滄溟十萬餘里。」根據資料敘述，下列何者正確？", "o": ["時代背景為明末", "奉命出航的是張騫", "出航最遠航行到非洲西岸", "資料所提的西洋，部分是指今日的東南亞"], "a": 3, "e": "資料講的是鄭和下西洋（永樂年間），西洋包含今日的東南亞。時代是明初，最遠到非洲東岸。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-zhenghe"], "chk": ""}, {"id": "h4-167", "no": 167, "c": "d6", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 20 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "美國的國家地理雜誌曾寫一篇專題報導，當西方航海家迪亞斯於 1498 年繞過非洲好望角於東非上岸時，村中長老告訴他在很久以前有一群「白色的人」，穿著絲綢，駕著大船，到訪他們的海岸。上文這批「白色的人」，到達東非的時間，領先了歐洲幾乎一個世紀。關於「白色的人」的敘述，下列何者正確？", "o": ["是因明朝海禁政策而在海上漂泊的倭寇", "出洋的目的在於尋找通往西方的新航道", "造成許多中國發明的物品傳入西方世界", "使得明帝國國威大盛，擴大了朝貢貿易的規模"], "a": 3, "e": "「白色的人」是鄭和的船隊，下西洋使明朝國威大盛，擴大了朝貢貿易的規模。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["h4-zhenghe"], "chk": ""}, {"id": "h4-168", "no": 168, "c": "d2", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 22 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "《明代的殞落》一書，描寫明末老百姓的心情。下列哪一項敘述最符合？", "o": ["皇帝大興文字獄，沒有人敢暢所欲言", "外族掌權，種族差別的政策令人深感不公", "到處都是流寇，人民的日子非常不好過啊", "遷都之後，皇帝還下令要皇族改漢姓、學漢語"], "a": 2, "e": "明末流寇四起，人民生活困苦。文字獄是清代；種族差別待遇是元代；改漢姓是北魏。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-169", "no": 169, "c": "d7", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 24 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "幾位同學課後陳述明清時代的對外貿易，以下何者的說明符合史實？", "o": ["明帝國不重視貿易，周邊國家多與中國進行走私貿易", "明初與清初曾頒布海禁，是為了對付倭寇與鄭氏", "明太祖派官員率艦隊下西洋，最遠到非洲東岸", "葡萄牙人開闢美洲到中國的航路，以白銀和中國交易"], "a": 1, "e": "明初海禁防倭寇、清初海禁打擊鄭氏，正確。派鄭和下西洋的是明成祖；開闢美洲到中國航路的是西班牙。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-170", "no": 170, "c": "d13", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 題組 (一) 26（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "臺灣的「甜不辣」，原意為日本料理中的「天婦羅」。「天婦羅」一詞是 tempero 的日式漢字寫法。16 世紀由傳教士傳入日本，在大齋期（天主教節日，指復活節六個半星期以前）期間因為禁吃獸肉，只能食用海鮮，因此傳入了裏麵粉和雞蛋油炸魚肉的烹調食物方法。在日本鎖國時期，傳教士最早可能將裏麵粉和雞蛋糊油炸魚肉的烹調方法傳入日本何地？", "o": ["京都", "長崎", "橫濱", "江戶"], "a": 1, "e": "日本鎖國時唯一的對外窗口是長崎。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-171", "no": 171, "c": "d13", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 題組 (一) 27（跨課）", "st": "考卷", "ctx": "臺灣的「甜不辣」，原意為日本料理中的「天婦羅」。「天婦羅」一詞是 tempero 的日式漢字寫法。16 世紀由傳教士傳入日本，在大齋期（天主教節日，指復活節六個半星期以前）期間因為禁吃獸肉，只能食用海鮮，因此傳入了裏麵粉和雞蛋油炸魚肉的烹調食物方法。", "fig": "", "q": "承上題，日本在鎖國時期，接觸的西方學術最主要是由下列何者帶入？", "o": ["西班牙傳教士", "葡萄牙商人", "荷蘭商人", "中國商人"], "a": 2, "e": "鎖國時期的西方學術主要由荷蘭商人帶入，稱為「蘭學」。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m1", "no": null, "c": "d11", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "利瑪竇在中國傳教時，採用了哪一種策略？", "o": ["要求教徒拆除祖先牌位", "穿儒服、說漢語，容許教徒祭祖祭孔", "只在宮廷傳教，不接觸士大夫", "以武力保護傳教"], "a": 1, "e": "利瑪竇尊重儒家習俗，容許教徒祭祖、祭孔，天主教才較能被士大夫接受。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m2", "no": null, "c": "d11", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "下列哪一項是明末清初由西方傳入中國的知識？", "o": ["火藥", "活字印刷術", "畫有經緯線的世界地圖", "指南針"], "a": 2, "e": "利瑪竇的《坤輿萬國全圖》帶來經緯線地圖；火藥、印刷術、指南針都是中國的發明。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m3", "no": null, "c": "d3", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "下列清朝的統治措施，哪一組屬於「高壓」？", "o": ["舉行科舉、禮遇明朝官員", "薙髮留辮、大興文字獄", "推崇儒學、編修典籍", "減免賦稅、獎勵開墾"], "a": 1, "e": "薙髮留辮、文字獄是高壓；科舉、禮遇明官是懷柔。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m4", "no": null, "c": "d3", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "建立清朝的民族，以及 1636 年改國號為「大清」的人，配對何者正確？", "o": ["蒙古族、忽必烈", "女真族、皇太極", "女真族、完顏阿骨打", "契丹族、耶律阿保機"], "a": 1, "e": "清朝由女真（滿洲）建立，皇太極在 1636 年改國號為大清；完顏阿骨打建立的是宋代的金國。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m5", "no": null, "c": "d6", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "鄭和下西洋與 15 世紀末歐洲人開闢新航路相比，下列何者正確？", "o": ["鄭和比較晚出發", "鄭和的目的是尋找殖民地", "鄭和早了將近一百年，目的在宣揚國威", "兩者都抵達美洲"], "a": 2, "e": "鄭和在 15 世紀初出航，比歐洲新航路早近一百年，目的是宣揚國威、擴大朝貢。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m6", "no": null, "c": "d6", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "鄭和下西洋最遠到達哪裡？", "o": ["日本", "非洲東岸", "歐洲西岸", "美洲西岸"], "a": 1, "e": "鄭和船隊經東南亞、印度洋，最遠到達非洲東岸。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m7", "no": null, "c": "d2", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "明末流寇興起的原因，不包括下列哪一項？", "o": ["天災造成饑荒", "官府重稅逼迫", "災民與飢兵結合", "清朝大興文字獄"], "a": 3, "e": "文字獄是清朝的政策；明末流寇是因為天災饑荒、重稅，災民與飢兵結合而起。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m8", "no": null, "c": "d2", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "西元 1644 年發生了哪兩件大事？", "o": ["李自成攻陷北京、清兵入關", "鄭和下西洋、遷都北京", "雍正禁教、平定新疆", "朱元璋建明、驅逐蒙古"], "a": 0, "e": "1644 年李自成攻陷北京、明朝滅亡，吳三桂隨即引清兵入關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m9", "no": null, "c": "d7", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "明代實施海禁，結果反而造成什麼現象？", "o": ["沿海居民全部改行務農", "走私貿易與武裝海商興起", "朝貢國家完全斷絕往來", "白銀停止流入"], "a": 1, "e": "東南沿海靠海維生，禁令迫使人民轉入走私，甚至形成武裝海商集團。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m10", "no": null, "c": "d7", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "清初嚴厲實施海禁、遷界，主要是為了對付誰？", "o": ["倭寇", "荷蘭人", "臺灣鄭氏", "流寇"], "a": 2, "e": "明代海禁防倭寇；清初海禁、遷界是為了切斷臺灣鄭氏的補給。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m11", "no": null, "c": "d1", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "明朝兩次建都的先後順序是？", "o": ["北京→南京", "南京→北京", "西安→北京", "臨安→南京"], "a": 1, "e": "明太祖建都應天（南京），明成祖遷都北京。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m12", "no": null, "c": "d1", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "明成祖把首都遷到北京，主要目的是什麼？", "o": ["方便對外貿易", "就近防禦北方蒙古", "躲避倭寇", "靠近景德鎮"], "a": 1, "e": "遷都北京是為了就近防禦蒙古，稱為「天子守國門」。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m13", "no": null, "c": "d12", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "「禮儀之爭」爭論的重點是什麼？", "o": ["中國教徒能不能祭祖、祭孔", "傳教士要不要薙髮", "教堂能不能建在北京", "能不能翻譯《聖經》"], "a": 0, "e": "羅馬教廷禁止中國教徒祭祖祭孔，引起康熙不滿，爆發禮儀之爭。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m14", "no": null, "c": "d12", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "清朝康熙、雍正、乾隆三位皇帝中，下令全面禁教的是誰？", "o": ["康熙", "雍正", "乾隆", "三位都有"], "a": 1, "e": "雍正因傳教士涉入宮廷政爭，下令全面禁教。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m15", "no": null, "c": "d10", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "明代後期貨幣制度的變化，下列何者正確？", "o": ["紙幣成為主要貨幣", "白銀與銅錢並用", "只使用黃金", "恢復以物易物"], "a": 1, "e": "白銀大量流入，形成大額用白銀、小額用銅錢的銀錢並用制度。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m16", "no": null, "c": "d10", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "明代大量白銀流入中國的主要原因是什麼？", "o": ["中國開採大量銀礦", "歐洲商人用美洲白銀購買中國商品", "蒙古人帶來白銀", "朝貢國家進貢白銀"], "a": 1, "e": "西班牙等歐洲商人用美洲白銀購買中國的絲綢、瓷器。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m17", "no": null, "c": "d13", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "日本鎖國期間，透過荷蘭人傳入的西方學問稱為什麼？", "o": ["蘭學", "理學", "國學", "西學東漸"], "a": 0, "e": "荷蘭人在長崎出島帶來的西方醫學、天文等知識，稱為「蘭學」。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m18", "no": null, "c": "d5", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "明清的朝貢貿易，外國必須先做到哪一件事？", "o": ["接受中國皇帝冊封", "派兵協助中國作戰", "改用中國文字", "繳交關稅"], "a": 0, "e": "外國要接受冊封、成為藩屬，才能以進貢名義來中國貿易。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m19", "no": null, "c": "d9", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "宋代引進的占城稻與明代引進的番薯，下列比較何者正確？", "o": ["都來自美洲", "占城稻來自越南，番薯來自美洲", "都來自越南", "占城稻來自美洲，番薯來自越南"], "a": 1, "e": "占城稻是宋代從越南引進；番薯是明代從美洲傳入。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "h4-m20", "no": null, "c": "d4", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "下列地區與將它納入清朝版圖的皇帝，配對何者正確？", "o": ["臺灣—康熙", "臺灣—乾隆", "新疆—康熙", "新疆—雍正"], "a": 0, "e": "康熙派施琅攻下臺灣；乾隆平定準噶爾，新疆才納入版圖。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}], "extras": [{"id": "compare", "title": "易混淆比較", "html": "<h3>1. 明代 vs. 清代 政治統治與邊防政策比較</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>明代（朱明王朝）</th><th>清代（滿清帝國）</th></tr></thead><tbody><tr><td><b>開國君主／背景</b></td><td>明太祖（朱元璋），驅逐蒙古建立漢人政權</td><td>清太宗皇太極改國號大清；世祖順治入關</td></tr><tr><td><b>主要北方邊患</b></td><td>早期為<b>蒙古</b>（韃靼、瓦剌），後期為東北<b>女真</b>（滿洲）</td><td>準噶爾部蒙古勢力（康熙、乾隆陸續平定）</td></tr><tr><td><b>首都選址考量</b></td><td>原南京，成祖後遷<b>北京</b>（「天子守國門」防蒙古）</td><td>定都<b>北京</b>，接續統治全中國與經營滿蒙東北腹地</td></tr><tr><td><b>民族治理方針</b></td><td>恢復漢族傳統儒家體制，排斥胡風</td><td><b>高壓與懷柔並行</b>（高壓：剃髮留辮、文字獄；懷柔：行科舉、禮遇明官）</td></tr><tr><td><b>極盛疆域範圍</b></td><td>以傳統長城以南漢人農業區為主</td><td>擴張納入<b>蒙古、新疆、西藏、臺灣</b>，奠定近代版圖</td></tr><tr><td><b>滅亡原因／事件</b></td><td>內部<b>李自成流寇攻陷北京</b>＋外部滿清入關</td><td>晚清遭遇西方列強侵逼與辛亥革命推翻</td></tr></tbody></table></div><h3>2. 明清官方「朝貢貿易」 vs. 民間「走私海商」</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>朝貢貿易（官方）</th><th>走私貿易（民間海商）</th></tr></thead><tbody><tr><td><b>主導角色</b></td><td>明、清朝廷官方主導（使節團、市舶司管轄）</td><td>東南沿海武裝海商（如顏思齊、鄭芝龍、倭寇集團）</td></tr><tr><td><b>政治前提</b></td><td>外國君主必須接受天朝「冊封」，以進貢名義來華</td><td>不受官方體制束縛，冒「違禁犯海」被捕風險甚至火拼</td></tr><tr><td><b>實施背景</b></td><td>貫徹「天朝體制」與展現天朝尊嚴禮儀秩序</td><td>「海禁政策」禁止民間私自出海，沿海民生被迫鋌而走險</td></tr><tr><td><b>主要特點</b></td><td>「厚往薄來」，政治象徵意義遠高於經濟實質收益</td><td>以營利為最高目標，貿易商品包括絲綢、瓷器、香料與白銀</td></tr><tr><td><b>活動航線</b></td><td>由朝廷官方船隊（如鄭和艦隊出使南洋、西洋）</td><td>活躍於日本、臺灣、東南亞各大島嶼與歐洲殖民據點</td></tr></tbody></table></div><h3>3. 中國西學東漸（明末清初） vs. 日本蘭學（江戶時期）</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>中國：西學東漸</th><th>日本：蘭學興起</th></tr></thead><tbody><tr><td><b>引進時期</b></td><td>明神宗（萬曆年間）至清康熙、雍正時期</td><td>江戶德川幕府實施鎖國政策期間（17～19世紀）</td></tr><tr><td><b>主要推手</b></td><td><b>天主教耶穌會傳教士</b>（如利瑪竇、湯若望、徐光啟合譯）</td><td>駐長崎商館之<b>荷蘭商人與醫師</b>（日本人向其求學）</td></tr><tr><td><b>引進內容</b></td><td>幾何數學（《幾何原本》）、天文曆法、火砲兵器、《坤輿萬國全圖》</td><td>近代西方解剖醫學、天文、物理、槍砲製造技術</td></tr><tr><td><b>開放管道</b></td><td>傳教士直接獲准進入京師（北京）並深入士大夫官場</td><td>嚴格隔離，僅准許荷蘭人滯留於九州<b>長崎出島</b></td></tr><tr><td><b>發展轉折</b></td><td>因「禮儀之爭」及宮廷政爭，雍正時<b>全面禁教</b>而中斷</td><td>日本維持鎖國下單向吸納，成為日後「明治維新」的近代化智識基石</td></tr></tbody></table></div>"}, {"id": "timeline", "title": "時間軸與流程", "html": "<h3>明清時期重大歷史演進時間軸</h3><div class=\"tbl\"><table><thead><tr><th>年代（西元）</th><th>事件名稱</th><th>核心重點</th></tr></thead><tbody><tr><td><b>1368 年</b></td><td>朱元璋建明朝</td><td>朱元璋稱帝於應天（南京），國號大明，隨即北伐驅逐蒙古勢力。</td></tr><tr><td><b>1405～1433 年</b></td><td><b>鄭和七次下西洋</b></td><td>明成祖派鄭和率龐大艦隊出使南洋、印度洋至非洲東岸，宣揚國威拓展朝貢體制。</td></tr><tr><td><b>15 世紀末</b></td><td>歐洲開闢新航路</td><td>歐洲地理大發現，美洲白銀大量流入東亞，番薯、玉米等新作物陸續傳入中國。</td></tr><tr><td><b>1582 年</b></td><td>耶穌會利瑪竇來華</td><td>利瑪竇抵華傳教，與徐光啟合譯《幾何原本》，開啟明末西學東漸與中西交流。</td></tr><tr><td><b>1636 年</b></td><td>皇太極定國號大清</td><td>東北女真族強盛，改族名為滿洲，皇太極改國號為「大清」。</td></tr><tr><td><b>1639 年前後</b></td><td><b>日本德川幕府鎖國</b></td><td>日本防範天主教勢力，實行鎖國體制，僅開放長崎允許中國與荷蘭商船貿易。</td></tr><tr><td><b>1644 年</b></td><td><b>明朝滅亡、清兵入關</b></td><td>李自成攻陷北京崇禎帝自縊；吳三桂引清軍入關消滅流寇，清世祖入主北京。</td></tr><tr><td><b>1683 年</b></td><td>清廷攻取臺灣</td><td>康熙帝派施琅擊降臺灣鄭氏政權，翌年設臺灣府納入清朝版圖。</td></tr><tr><td><b>18 世紀初（1723 年）</b></td><td><b>雍正皇帝下令禁教</b></td><td>因「禮儀之爭」及傳教士介入清廷宮廷皇位繼承政爭，雍正帝正式全面禁教。</td></tr><tr><td><b>18 世紀中葉</b></td><td>乾隆平定新疆</td><td>乾隆帝平定天山南北準噶爾與回部叛亂，將新疆正式納入版圖，完成盛世疆域。</td></tr></tbody></table></div><h3>明清政權交替與東亞海陸變動流程圖</h3><pre class=\"flow\">【北方政權變動】：\n  明末天災饑荒 ──&gt; 災民與飢兵集結 ──&gt; 李自成攻陷北京（明亡）\n                                            │\n  東北女真崛起（後金→大清）──(吳三桂引清兵入關)──▼\n                                     清兵入主北京，建立全國統治（滿清盛世）\n\n【東亞海洋貿易與思想變動】：\n  歐洲大航海時代 ──&gt; 跨洋航線建立 ──&gt; 美洲白銀大量流入（銀錢並用制確立）\n                                  └──&gt; 美洲新作物傳入（番薯、玉米解救人口饑荒）\n                                  └──&gt; 傳教士東來（利瑪竇西學東漸）\n                                            │\n                             ┌──────────────┴──────────────┐\n                             ▼                             ▼\n                  清初禮儀之爭＋宮廷政爭           日本江戶幕府懼外教抗拒動亂\n                             │                             │\n                        雍正全面禁教                  實施鎖國（獨尊長崎蘭學）</pre>"}, {"id": "charts", "title": "圖表判讀", "html": "<h3>1. 《明代後期周邊民族與倭寇、流寇示意圖》</h3><figure class=\"cimg\"><img src=\"img/h4-ming.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>明代後期周邊民族與倭寇、流寇示意圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《明代後期周邊民族與外患動亂形勢圖》。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. 北方邊界外圍長城以北標註「蒙古（韃靼、瓦剌）」，為明初至中期的長期邊防大患。</p><p class=\"li sub\">2. 東北長白山與黑龍江流域標註「女真（滿洲）」，為明末最危險的外患政權。</p><p class=\"li sub\">3. 陝西與華北腹地分布斜線或箭頭標註「早期流寇活動區域（李自成進京路線）」。</p><p class=\"li sub\">4. 東南沿海浙江、福建、廣東一帶標註密集的「倭寇活動與登陸掠奪箭頭」。</p><p class=\"li\"><b>常見判讀方式</b>：若地圖同時呈現「北邊蒙古」、「東北女真」、「東南沿海倭寇」與「內地陝西流寇」四大危機，即可判定為「明代後期（明朝末年）」的內憂外患全景圖。</p><h3>2. 《清代盛世疆域圖》</h3><figure class=\"cimg\"><img src=\"img/h4-qing.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>清代盛世疆域圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《清代康雍乾盛世版圖示意圖》。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. 清朝疆域遠超越明代的兩京十三省傳統漢地，向北延伸納入蒙古高原（內外蒙古），東北抵達外興安嶺與黑龍江流域。</p><p class=\"li sub\">2. 西北納入「新疆（天山南北路）」、西南包含「西藏」與青海。</p><p class=\"li sub\">3. 東南方將「臺灣」與澎湖正式收歸行省管轄。</p><p class=\"li\"><b>常見判讀方式</b>：秋海棠形狀的版圖即為大清盛世疆域圖。常考題型：要求區分臺灣、西藏、新疆是於清朝何時納入版圖（康雍乾時期），或標示出何地為清朝皇帝的「龍興發祥發源地」（東北滿洲地區）。</p><h3>3. 《鄭和下西洋航線與朝貢國家圖》</h3><figure class=\"cimg\"><img src=\"img/h4-zhenghe.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>鄭和下西洋路線圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《鄭和七次下西洋航海路線圖》。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. 航線起點為南京（應天府）及江蘇劉家港，經福建沿海（長樂）出海。</p><p class=\"li sub\">2. 航行主要穿越中南半島各國、馬六甲海峽、印度半島沿岸各港（如古里）。</p><p class=\"li sub\">3. 橫越阿拉伯海（印度洋），最遠深入阿拉伯半島（阿丹、麥加）以及非洲東岸（木骨都束、麻林地）。</p><p class=\"li\"><b>常見判讀方式</b>：若箭頭自中國東南沿海橫越東南亞並遠抵「非洲東岸」，且年代標註為 15 世紀初，必定為「鄭和下西洋朝貢圖」，切勿與漢唐絲綢之路或 15 世紀末西方達伽馬、哥倫布的新航路混淆。</p><h3>4. 《新航路開闢後全球經濟與美洲物產流向圖》</h3><figure class=\"cimg\"><img src=\"img/h4-global.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>葡萄牙、西班牙人新航路與全球經濟網絡圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《大航海時代跨太平洋與印度洋商品貿易網絡圖》。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. <b>美洲物產流向中國</b>：白銀、番薯、玉米、馬鈴薯橫越太平洋或經歐洲轉入中國。</p><p class=\"li sub\">2. <b>中國商品流向歐美世界</b>：絲綢、瓷器、茶葉由澳門或馬尼拉港裝船運往歐洲及美洲。</p><p class=\"li\"><b>常見判讀方式</b>：題目遮蓋物流名稱時，從美洲指向亞洲的箭頭通常填寫「白銀」、「番薯／玉米」；由中國指向外洋的箭頭通常填寫「生絲／絲綢」、「瓷器」。</p>"}, {"id": "tips", "title": "口訣與防錯", "html": "<h3>考試核心防陷阱口訣</h3><div class=\"poem\"><b>「明太驅蒙定南京，成祖遷北長城營；</b></div><div class=\"poem\"><b>鄭和七航揚海威，海禁反引倭寇橫；</b></div><div class=\"poem\"><b>天災流寇李自成，三桂開關清入城；</b></div><div class=\"poem\"><b>高壓剃髮文字獄，懷柔科舉撫民情；</b></div><div class=\"poem\"><b>美洲銀薯接全球，景德名瓷海外求；</b></div><div class=\"poem\"><b>瑪竇幾何傳天算，雍正爭位閉鎖關；</b></div><div class=\"poem\"><b>日本懼教開長崎，唯有荷蘭傳蘭學。」</b></div><p class=\"li\"><b>防錯關鍵 1（明朝兩次建都的先後順序）</b>：明太祖朱元璋起兵於南方，開國建都於<b>應天（南京）</b>；明成祖奪位後為「防範蒙古」才遷都<b>北京</b>，號稱「天子守國門」。切勿記反先後順序。</p><p class=\"li\"><b>防錯關鍵 2（清廷雙面手法的對應）</b>：「剃髮留辮」、「大興文字獄」是<b>高壓</b>政策；「禮遇明朝遺臣降將」、「照常舉行科舉」是<b>懷柔</b>政策。題目常要求分類兩者，絕不可搞混。</p><p class=\"li\"><b>防錯關鍵 3（盛世帝王順序與事蹟）</b>：清代順序為<b>康熙 → 雍正 → 乾隆</b>。攻取臺灣的是<b>康熙</b>（施琅）；全面下令禁教的是<b>雍正</b>（因政爭與禮儀之爭）；平定準噶爾確立新疆版圖的是<b>乾隆</b>。</p><p class=\"li\"><b>防錯關鍵 4（外來農作物引進朝代）</b>：</p><p class=\"li sub\">• <b>占城稻（早熟稻）</b>是<b>宋代</b>引進自越南。</p><p class=\"li sub\">• <b>番薯、玉米、馬鈴薯</b>是<b>明清時期</b>因歐洲開闢新航路自美洲引進。兩者引進背景與來源完全不同，是段考必考的對照混淆點！</p><p class=\"li\"><b>防錯關鍵 5（明末傳教與清初禁教的核心人物）</b>：</p><p class=\"li sub\">• 引進西學最成功的是<b>利瑪竇</b>（與徐光啟合譯《幾何原本》），採用包容儒家祭祖祭孔策略。</p><p class=\"li sub\">• 導致中斷中西交流的是羅馬教廷反對祭孔引發的「<b>禮儀之爭</b>」，以及<b>雍正帝</b>因傳教士介入宮廷爭位所發布的「<b>全面禁教令</b>」。</p><p class=\"li\"><b>防錯關鍵 6（日本鎖國下的唯一特例）</b>：日本德川幕府鎖國期間，並非完全與世隔絕，而是在「<b>長崎</b>」准許「<b>中國</b>」與「<b>荷蘭</b>」商船貿易，荷蘭帶來的西方科技稱為「<b>蘭學</b>」。</p>"}]});
